window.BANK['a5']['a5-1-1'] = [
  {"q":"أنواع الكلمة في اللغة العربية هي:","o":["اسم وفعل وحرف","مبتدأ وخبر وفاعل","ماضٍ ومضارع وأمر","مفرد ومثنى وجمع"],"a":0,"why":"الكلمة في اللغة العربية ثلاثة أنواع فقط: اسم، وفعل، وحرف. أي كلمة تقرؤها لا بد أن تكون واحدة منها، ولا يوجد نوع رابع.","ow":["","مبتدأ وخبر وفاعل هذه وظائف الكلمات في الجملة، وليست أنواع الكلمة.","ماضٍ ومضارع وأمر هذه أنواع الفعل فقط، وليست كل أنواع الكلمة.","مفرد ومثنى وجمع هذه أعداد الاسم، وليست أنواع الكلمة."]},
  {"q":"أي الكلمات الآتية اسم؟","o":["يلعبُ","الولدُ","في","اكتبْ"],"a":1,"why":"الولدُ اسم لأن فيها ال التعريف، وهي من علامات الاسم الثلاث: التنوين وال التعريف والجر. ومعناها واضح وحدها من غير زمن.","ow":["يلعبُ فعل مضارع لأنه يدل على حدث هو اللعب مرتبط بزمن.","","في حرف جر، معناه لا يتم إلا مع كلمة بعده.","اكتبْ فعل أمر لأنه يطلب حدوث الكتابة."]},
  {"q":"أي الكلمات الآتية تُعدّ حرفًا؟","o":["مدرسةٌ","درسَ","عن","يقرأُ"],"a":2,"why":"عن حرف جر، ومعناه لا يظهر وحده، فلا نفهم «عن» إلا إذا جاء بعدها اسم مثل: عن الدرس.","ow":["مدرسةٌ اسم لأن فيها تنوينًا ومعناها واضح بنفسها.","درسَ فعل ماضٍ لأنه يدل على حدث انتهى.","","يقرأُ فعل مضارع لأنه يدل على حدث يقع الآن أو سيقع."]},
  {"q":"أي الكلمات الآتية فعل؟","o":["إلى","كتابٌ","الباب","ذهبَ"],"a":3,"why":"ذهبَ فعل لأنه يدل على حدث هو الذهاب، وهذا الحدث انتهى، فهو فعل ماضٍ مقترن بزمن. أما إلى فحرف، وكتابٌ والباب اسمان.","ow":["إلى حرف جر، ولا يدل على حدث.","كتابٌ اسم لأن فيه تنوينًا، ولا يقترن بزمن.","الباب اسم لأن فيه ال التعريف، ولا يدل على حدث.",""]},
  {"q":"في جملة: ذهبَ عليٌّ إلى المسجد، الكلمة التي هي حرف:","o":["ذهبَ","عليٌّ","إلى","المسجد"],"a":2,"why":"إلى حرف جر، لا يتم معناه إلا مع اسم بعده مثل: إلى المسجد. أما ذهبَ ففعل، وعليٌّ والمسجد اسمان.","ow":["ذهبَ فعل ماضٍ لأنه يدل على حدث انتهى.","عليٌّ اسم شخص، وفيه تنوين، ومعناه واضح بلا زمن.","","المسجد اسم لأن فيه ال التعريف، وهو مجرور بعد حرف الجر."]},
  {"q":"الفعل الماضي هو ما دلّ على حدث:","o":["يحدث الآن أو سيحدث","انتهى","مطلوب حدوثه","غير مقترن بزمن"],"a":1,"why":"الفعل الماضي هو ما دلّ على حدث انتهى قبل زمن الكلام، مثل: كتبَ وذهبَ وجلسَ. فالحدث وقع وانتهى.","ow":["هذا تعريف الفعل المضارع، وهو الحدث الذي يقع الآن أو سيقع.","","هذا تعريف فعل الأمر، وهو طلب حدوث الفعل.","الفعل الماضي مقترن بزمن هو الزمن الماضي، فعبارة غير مقترن بزمن لا تناسبه."]},
  {"q":"نوع الفعل <b>يقرأُ</b>:","o":["ماضٍ","أمر","اسم","مضارع"],"a":3,"why":"يقرأُ يدل على حدث هو القراءة، وهي تحدث الآن أو ستحدث بعد قليل. وكل فعل يدل على حدث يقع الآن أو سيقع فهو فعل مضارع.","ow":["الماضي حدث انتهى مثل قرأَ، وهنا الحدث لم ينتهِ.","الأمر طلب حدوث الفعل مثل اقرأْ، وليس فيها طلب.","يقرأُ يدل على حدث وزمن، فهو فعل لا اسم.",""]},
  {"q":"نوع الفعل <b>ادرسْ</b>:","o":["مضارع","ماضٍ","أمر","حرف"],"a":2,"why":"ادرسْ فيه طلب من المتكلم أن يدرس غيره. وطلب حدوث الفعل هو فعل الأمر، مثل: اكتبْ وادرسْ واجلسْ.","ow":["المضارع يدل على حدث يقع الآن مثل يدرسُ، وليس فيها طلب.","الماضي حدث انتهى مثل درسَ، وليس فيها حدث منتهٍ.","","ادرسْ تدل على حدث، فهي فعل وليست حرفًا."]},
  {"q":"نوع الفعل <b>جلسَ</b>:","o":["ماضٍ","أمر","مضارع","اسم"],"a":0,"why":"جلسَ فعل يدل على حدث الجلوس، وقد انتهى هذا الحدث، فهو فعل ماضٍ. ونعرف الماضي بأنه حدث وقع وخلص قبل الآن.","ow":["","الأمر طلب حدوث الفعل مثل اجلسْ، وليس فيها طلب.","المضارع حدث يقع الآن أو سيقع مثل يجلسُ، وهنا الحدث انتهى.","جلسَ تدل على حدث مقترن بزمن، فهي فعل لا اسم."]},
  {"q":"أي مما يأتي من علامات الاسم؟","o":["سوف","قد","لم","ال التعريف"],"a":3,"why":"ال التعريف من علامات الاسم الثلاث: التنوين وال التعريف والجر، مثل: الكتاب، المدرسة.","ow":["سوف حرف يدخل على الفعل المضارع، وليس علامة للاسم.","قد حرف يدخل على الفعل، وليس علامة للاسم.","لم حرف جزم يدخل على الفعل المضارع، وليس علامة للاسم.",""]},
  {"q":"علامة الاسم في كلمة <b>مدرسةٌ</b>:","o":["التنوين","ال التعريف","الجر","ألف الاثنين"],"a":0,"why":"مدرسةٌ في آخرها ضمتان، وهما التنوين. والتنوين علامة من علامات الاسم، فتدل الكلمة على أنها اسم.","ow":["","ليس في الكلمة ال التعريف، فهي مدرسةٌ وليست المدرسة.","لا يوجد قبل الكلمة حرف جر مثل في أو إلى لتكون مجرورة.","ألف الاثنين علامة في الأفعال مثل كتبا، وليست في الكلمة."]},
  {"q":"علامة الاسم في كلمة <b>الكتاب</b>:","o":["التنوين","الجر","ال التعريف","واو الجماعة"],"a":2,"why":"الكتاب بدأت بال التعريف، وهي علامة من علامات الاسم. ولهذا نحكم بأنها اسم، ولا نحتاج إلى تنوين فيها.","ow":["ليس في آخر الكلمة تنوين، بل آخرها حرف عادي بلا تنوين.","لا يوجد قبلها حرف جر، فهي ليست مجرورة هنا.","","واو الجماعة تأتي مع الأفعال مثل كتبوا، وليست في الكلمة."]},
  {"q":"اللفظ الذي لا يظهر معناه إلا مع غيره هو:","o":["الفعل","الحرف","الاسم","الماضي"],"a":1,"why":"الحرف هو لفظ لا يظهر معناه إلا مع غيره، فلا نفهم «إلى» وحدها بل نقول: إلى المدرسة.","ow":["الفعل له معنى وحده وهو الحدث مع الزمن.","","الاسم له معنى في نفسه ولا يحتاج إلى كلمة أخرى ليظهر معناه.","الماضي نوع من أنواع الفعل، وليس هو اللفظ المقصود."]},
  {"q":"أي الكلمات الآتية من حروف الجر؟","o":["كتبَ","يكتبُ","إلى","كتابٌ"],"a":2,"why":"إلى من حروف الجر مثل: عن وفي ومن وإلى. وهي حروف تدخل على الأسماء وتجرها، فنقول: إلى المدرسة بكسر الآخر.","ow":["كتبَ فعل ماضٍ يدل على حدث انتهى، وليس حرفًا.","يكتبُ فعل مضارع يدل على حدث، وليس حرف جر.","","كتابٌ اسم لأن فيه تنوينًا، وليس حرف جر."]},
  {"q":"الكلمة التي تدل على حدث مرتبط بزمن هي:","o":["الفعل","الاسم","الحرف","التنوين"],"a":0,"why":"الفعل هو الكلمة التي تدل على حدث مرتبط بزمن، مثل: ذهبَ ويلعبُ واكتبْ. فنعرف متى وقع الحدث أو يقع.","ow":["","الاسم لا يقترن بزمن، فلا يدل على حدث مرتبط به.","الحرف لا يظهر معناه إلا مع غيره، ولا يدل على حدث.","التنوين علامة من علامات الاسم، وليس كلمة."]},
  {"q":"العبارة: الكلمة في العربية اسم أو فعل أو حرف.","o":["صح","خطأ"],"a":0,"why":"هذه العبارة صحيحة، فالكلمة في اللغة العربية ثلاثة أنواع فقط هي: الاسم والفعل والحرف، ولا يوجد نوع رابع.","ow":["","العبارة صحيحة، ولا يوجد نوع رابع للكلمة غير الأنواع الثلاثة."]},
  {"q":"العبارة: الفعل المضارع يدل على حدث انتهى.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ لأن الفعل المضارع يدل على حدث يقع الآن أو سيقع. أما الذي يدل على حدث انتهى فهو الفعل الماضي.","ow":["هذه العبارة صحيحة في الماضي فقط، أما المضارع فهو حدث يقع الآن أو سيقع.",""]},
  {"q":"العبارة: كلمة <b>في</b> من الحروف.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فكلمة في من حروف الجر، ومعناها لا يتم وحدها بل مع اسم بعدها مثل: في المدرسة.","ow":["","العبارة صحيحة، فكلمة في حرف جر وليست اسمًا ولا فعلًا."]},
  {"q":"العبارة: فعل الأمر يدل على طلب حدوث الفعل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، ففعل الأمر يطلب فيه المتكلم حدوث الفعل من غيره، مثل: اكتبْ وادرسْ.","ow":["","العبارة صحيحة، فالأمر هو طلب حدوث الفعل."]},
  {"q":"العبارة: الاسم يدل على معنى في نفسه مقترن بزمن.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، لأن الاسم هو ما دلّ على معنى في نفسه دون اقتران بزمن. أما الفعل فهو الذي يقترن بزمن.","ow":["لا تصح العبارة، لأن الاسم لا يقترن بزمن، والمقترن بزمن هو الفعل.",""]},
];
window.BANK['a5']['a5-1-2'] = [
  {"q":"الجملة التي تبدأ بفعل تسمى جملة:","o":["اسمية","فعلية","ندائية","استفهامية"],"a":1,"why":"الجملة التي تبدأ بفعل تسمى فعلية، وركناها الفعل والفاعل. مثل: يقرأُ الطالبُ، فهي تبدأ بالفعل يقرأُ.","ow":["الاسمية تبدأ باسم وليس بفعل.","","الندائية تبدأ بحرف النداء مثل يا، وليست هي القاعدة المطلوبة.","الاستفهامية تبدأ بأداة استفهام، وليست نوعًا من نوعي الجملة هنا."]},
  {"q":"تتكون الجملة الاسمية من:","o":["الفعل والفاعل","الماضي والمضارع","المبتدأ والخبر","المنادى والنداء"],"a":2,"why":"الجملة الاسمية تتكون من ركنين: المبتدأ وهو الاسم الذي نبدأ به، والخبر وهو ما يتم به المعنى. مثل: العلمُ نورٌ.","ow":["الفعل والفاعل ركنا الجملة الفعلية، وليس الاسمية.","الماضي والمضارع من أنواع الفعل، وليسا ركني الجملة.","","المنادى والنداء من أركان أسلوب النداء، وليسا ركني الجملة الاسمية."]},
  {"q":"تتكون الجملة الفعلية من:","o":["المبتدأ والخبر","الفعل والفاعل","الاسم والحرف","الصفة والموصوف"],"a":1,"why":"الجملة الفعلية تتكون من فعل يدل على حدث وفاعل قام به، مثل: كتبَ الطالبُ، فالفعل كتبَ والفاعل الطالبُ.","ow":["المبتدأ والخبر ركنا الجملة الاسمية، وليس الفعلية.","","الاسم والحرف من أنواع الكلمات، وليسا ركني الجملة.","الصفة والموصوف تركيب آخر، وليسا ركني الجملة الفعلية."]},
  {"q":"نوع الجملة: <b>العلمُ نورٌ</b>","o":["اسمية","فعلية","ندائية","شرطية"],"a":0,"why":"العلمُ نورٌ تبدأ بالاسم العلم، فهي جملة اسمية. العلمُ مبتدأ، ونورٌ خبر يكمّل المعنى.","ow":["","الفعلية تبدأ بفعل، وهذه تبدأ باسم.","الندائية تبدأ بحرف نداء مثل يا، وهذه تبدأ بالاسم العلم.","الشرطية تحتاج أداة شرط، وهذه الجملة لا فيها أداة شرط."]},
  {"q":"نوع الجملة: <b>يقرأُ الطالبُ الكتابَ</b>","o":["اسمية","ندائية","فعلية","استفهامية"],"a":2,"why":"يقرأُ الطالبُ الكتابَ تبدأ بالفعل يقرأُ، فهي جملة فعلية. الفاعل الطالبُ، لأنه هو الذي يقرأ.","ow":["الاسمية تبدأ باسم، وهذه تبدأ بفعل هو يقرأُ.","الندائية تبدأ بحرف نداء مثل يا، وهذه تبدأ بفعل.","","الاستفهامية تبدأ بأداة استفهام، وهذه الجملة تبدأ بفعل."]},
  {"q":"المبتدأ في جملة: <b>الأمانةُ طاعةٌ لله</b>","o":["الأمانةُ","طاعةٌ","لله","الجملة كلها"],"a":0,"why":"المبتدأ هو الاسم الذي نبدأ به الجملة الاسمية. في الأمانةُ طاعةٌ لله بدأنا بكلمة الأمانة، فهي المبتدأ.","ow":["","طاعةٌ هي الخبر لأنها أكملت المعنى، وليست المبتدأ.","لله جار ومجرور يتمم الخبر، وليس هو الاسم الذي بدأنا به.","المبتدأ كلمة واحدة هي الاسم الأول، وليس الجملة كلها."]},
  {"q":"الخبر في جملة: <b>الكتابُ مفيدٌ</b>","o":["الكتابُ","لا يوجد خبر","مفيدٌ","الجملة"],"a":2,"why":"الخبر هو ما يتم به المعنى ويقول شيئًا عن المبتدأ. في الكتابُ مفيدٌ نقول عن الكتاب إنه مفيد، فالخبر مفيدٌ.","ow":["الكتابُ هو المبتدأ لأننا بدأنا به الكلام، وليس الخبر.","كل جملة اسمية فيها خبر، وهنا الخبر موجود وهو مفيدٌ.","","الجملة كلها ليست هي الخبر، بل الخبر جزء منها هو ما كمّل المعنى."]},
  {"q":"الفاعل في جملة: <b>تُسهمُ التحصيناتُ في حماية الأفراد</b>","o":["تُسهمُ","التحصيناتُ","حماية","الأفراد"],"a":1,"why":"الفاعل هو من قام بالفعل. في تُسهمُ التحصيناتُ في حماية الأفراد التحصينات هي التي تسهم، فهي الفاعل.","ow":["تُسهمُ هو الفعل نفسه، وليس من قام به.","","حماية اسم مجرور بعد حرف الجر في، وليست من قام بالحدث.","الأفراد هم الذين تحميهم التحصينات، وليسوا الفاعل."]},
  {"q":"الفعل في جملة: <b>يساعدُ الطالبُ زميلَه</b>","o":["الطالبُ","زميلَه","لا يوجد فعل","يساعدُ"],"a":3,"why":"الفعل هو الكلمة التي تدل على حدث، وفي الجملة يساعدُ يدل على حدث المساعدة، فهو الفعل. والطالبُ هو الفاعل.","ow":["الطالبُ اسم وهو الفاعل الذي قام بالمساعدة، وليس الفعل.","زميلَه هو من تمت مساعدته، وهو اسم وليس فعلًا.","في الجملة فعل واضح هو يساعدُ، لأنها جملة فعلية.",""]},
  {"q":"أي الجمل الآتية فعلية؟","o":["الشمسُ ساطعةٌ","الأمانةُ طاعةٌ لله","يحرصُ المسلمُ على فروضه","الصدقُ منجاةٌ"],"a":2,"why":"الجملة الفعلية هي التي تبدأ بفعل، ويحرصُ فعل مضارع، فجملة يحرصُ المسلمُ على فروضه فعلية.","ow":["الشمسُ ساطعةٌ تبدأ بالاسم الشمس، فهي اسمية.","الأمانةُ طاعةٌ لله تبدأ بالاسم الأمانة، فهي اسمية.","","الصدقُ منجاةٌ تبدأ بالاسم الصدق، فهي اسمية."]},
  {"q":"أي الجمل الآتية اسمية؟","o":["يقرأُ عمرُ الدرسَ","الكتابُ مفيدٌ","تكتبُ سارةُ الواجبَ","يلعبُ الأولادُ"],"a":1,"why":"الجملة الاسمية هي التي تبدأ باسم. الكتابُ مفيدٌ تبدأ بالاسم الكتاب، والكتاب مبتدأ ومفيدٌ خبر.","ow":["يقرأُ عمرُ الدرسَ تبدأ بالفعل يقرأُ، فهي فعلية.","","تكتبُ سارةُ الواجبَ تبدأ بالفعل تكتبُ، فهي فعلية.","يلعبُ الأولادُ تبدأ بالفعل يلعبُ، فهي فعلية."]},
  {"q":"الفاعل هو:","o":["الاسم الذي نبدأ به الجملة الاسمية","ما يتم به المعنى","من قام بالحدث","حرف جر"],"a":2,"why":"الفاعل هو من قام بالحدث، فإذا قلنا كتبَ الطالبُ فالطالب هو الذي كتب، فهو الفاعل.","ow":["هذا تعريف المبتدأ، وهو الاسم الذي نبدأ به الجملة الاسمية.","هذا تعريف الخبر، وهو ما يتم به المعنى.","","حرف الجر كلمة معناها لا يتم وحدها، وليس هو الفاعل."]},
  {"q":"المبتدأ هو:","o":["من قام بالفعل","الاسم الذي نبدأ به الجملة الاسمية","ما دلّ على حدث","حرف نداء"],"a":1,"why":"المبتدأ هو الاسم الذي نبدأ به الجملة الاسمية، وهو أول ركنيها، والخبر يكمّل معناه. مثل: الصدقُ منجاةٌ.","ow":["هذا تعريف الفاعل، وهو من قام بالفعل في الجملة الفعلية.","","ما دلّ على حدث هو الفعل.","حرف النداء مثل يا، وليس هو المبتدأ."]},
  {"q":"الخبر هو:","o":["ما دلّ على حدث","من قام بالفعل","الاسم الذي نبدأ به","ما يتم به المعنى"],"a":3,"why":"الخبر هو ما يتم به المعنى بعد المبتدأ. في الصدقُ منجاةٌ قلنا الصدق، فيسأل السامع: ما هو؟ فتكمل: منجاةٌ، فهي الخبر.","ow":["ما دلّ على حدث هو الفعل، وليس الخبر.","من قام بالفعل هو الفاعل، وليس الخبر.","الاسم الذي نبدأ به الجملة الاسمية هو المبتدأ، وليس الخبر.",""]},
  {"q":"المعيار الذي نعرف به نوع الجملة هو النظر إلى:","o":["أول كلمة","آخر كلمة","عدد الكلمات","علامات الترقيم"],"a":0,"why":"نعرف نوع الجملة من أول كلمة فيها: إن كانت اسمًا فالجملة اسمية، وإن كانت فعلًا فالجملة فعلية.","ow":["","آخر كلمة لا تحدد نوع الجملة، فقد تكون اسمًا في الاسمية والفعلية معًا.","عدد الكلمات لا علاقة له بنوع الجملة، فقد تكون قصيرة أو طويلة.","علامات الترقيم لا تحدد نوع الجملة، فالنوع يتحدد بأول كلمة."]},
  {"q":"العبارة: الجملة التي تبدأ بفعل تسمى فعلية.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالجملة التي تبدأ بفعل تسمى فعلية، مثل: يكتبُ الطالبُ، وتتكون من فعل وفاعل.","ow":["","العبارة صحيحة، فالقاعدة أن أول كلمة فعل تجعل الجملة فعلية."]},
  {"q":"العبارة: المبتدأ والخبر منصوبان دائمًا.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، لأن المبتدأ والخبر مرفوعان دائمًا وليسا منصوبين. فنقول: الصدقُ منجاةٌ بالضم.","ow":["المنصوب ليس حكم المبتدأ والخبر، فهما مرفوعان دائمًا.",""]},
  {"q":"العبارة: الفاعل هو من قام بالحدث.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالفاعل هو من قام بالحدث، مثل الطالب في جملة: يكتبُ الطالبُ الواجبَ.","ow":["","العبارة صحيحة، فتعريف الفاعل هو من قام بالحدث."]},
  {"q":"العبارة: <b>الطالبُ مجتهدٌ</b> جملة فعلية.","o":["صح","خطأ"],"a":1,"why":"الطالبُ مجتهدٌ تبدأ بالاسم الطالب، فهي جملة اسمية ركناها المبتدأ الطالبُ والخبر مجتهدٌ، وليست فعلية.","ow":["هذه العبارة صحيحة لو بدأت الجملة بفعل، لكنها هنا تبدأ باسم فهي اسمية.",""]},
  {"q":"العبارة: <b>يكتبُ الطالبُ الواجبَ</b> جملة فعلية.","o":["صح","خطأ"],"a":0,"why":"يكتبُ الطالبُ الواجبَ تبدأ بالفعل يكتبُ وهو يدل على حدث الكتابة، فهي جملة فعلية. الفعل يكتبُ والفاعل الطالبُ.","ow":["","العبارة صحيحة، فالجملة تبدأ بفعل، فهي فعلية."]},
];
window.BANK['a5']['a5-1-3'] = [
  {"q":"أي الكلمات الآتية مؤنث؟","o":["قلمٌ","مسطرةٌ","كتابٌ","بابٌ"],"a":1,"why":"مسطرةٌ اسم مؤنث، لأننا نقول عنها: هذه مسطرة. أما قلم وكتاب وباب فنقول عنها هذا، فهي مذكرة.","ow":["قلم نقول عنه هذا قلم، فهو مذكر.","","كتاب نقول عنه هذا كتاب، فهو مذكر.","باب نقول عنه هذا باب، فهو مذكر."]},
  {"q":"كلمة <b>بابٌ</b> اسم:","o":["مؤنث","مثنى","مذكر","جمع"],"a":2,"why":"بابٌ اسم مذكر، لأننا نقول: هذا باب. والاسم المذكر هو ما يدل على مذكر ونشير إليه بهذا.","ow":["المؤنث نقول عنه هذه، ولا نقول هذه باب.","باب تدل على واحد، فهي مفرد وليست مثنى.","","باب مفرد، والجمع يدل على ثلاثة فأكثر."]},
  {"q":"مثنى كلمة <b>معلِّمٌ</b> هو:","o":["معلِّمان","معلِّمون","معلِّمات","معلِّمتان"],"a":0,"why":"المثنى يتكون بإضافة ألف ونون إلى المفرد. فمعلِّم تصبح معلِّمان، وتدل على اثنين، وهو مثنى مذكر.","ow":["","معلِّمون جمع مذكر، وتدل على ثلاثة فأكثر.","معلِّمات جمع مؤنث، وتدل على ثلاث فأكثر.","معلِّمتان مثنى مؤنث، أما مثنى المذكر فهو معلمان."]},
  {"q":"مثنى كلمة <b>معلِّمةٌ</b> هو:","o":["معلِّمات","معلِّمتان","معلِّمان","معلِّمون"],"a":1,"why":"المفرد المؤنث معلِّمةٌ، وعند التثنية نضيف ألف ونون فتصبح معلِّمتان، وتدل على اثنتين.","ow":["معلِّمات جمع مؤنث، وليست مثنى.","","معلِّمان مثنى مذكر، أما المؤنث فمعلِّمتان.","معلِّمون جمع مذكر، وليست مثنى المؤنثة."]},
  {"q":"يتكوّن المثنى بزيادة على المفرد:","o":["واو ونون","ألف وتاء","ألف ونون","ياء فقط"],"a":2,"why":"لتكوين المثنى نضيف ألفًا ونونًا إلى آخر المفرد، مثل: كتاب وكتابان، وتلميذة وتلميذتان، ومعلم ومعلمان.","ow":["الواو والنون تستخدم في جمع المذكر مثل معلمون.","الألف والتاء تستخدم في جمع المؤنث مثل معلمات.","","الياء فقط لا تكفي لتكوين المثنى، بل نحتاج إلى ألف ونون."]},
  {"q":"جمع المذكر السالم من كلمة <b>معلِّمٌ</b>:","o":["معلِّمان","معلِّمتان","معلِّمات","معلِّمون"],"a":3,"why":"جمع المذكر السالم يتكون بزيادة واو ونون على المفرد دون أن يتغير شكله، فمعلِّم تصبح معلِّمون وتدل على ثلاثة فأكثر.","ow":["معلِّمان مثنى، وليست جمعًا.","معلِّمتان مثنى مؤنث، وليست جمع مذكر.","معلِّمات جمع المؤنثة، وليس المذكر.",""]},
  {"q":"جمع المؤنث السالم من كلمة <b>معلِّمةٌ</b>:","o":["معلِّمات","معلِّمون","معلِّمتان","معلِّمان"],"a":0,"why":"جمع المؤنث السالم يتكون بزيادة ألف وتاء على المفرد، فنحذف التاء المربوطة ونزيد ألفًا وتاء، فمعلِّمة تصبح معلِّمات.","ow":["","معلِّمون جمع مذكر وليس جمع المؤنث.","معلِّمتان مثنى مؤنث، وتدل على اثنتين فقط.","معلِّمان مثنى مذكر، وليس جمع مؤنث."]},
  {"q":"أي الكلمات الآتية مثنى؟","o":["تلاميذ","تلميذان","تلميذ","تلميذات"],"a":1,"why":"تلميذان فيها ألف ونون زائدتان على المفرد تلميذ، فهي مثنى لأنها تدل على اثنين فقط، مثل معلمان وكتابان.","ow":["تلاميذ جمع، لأنها تدل على ثلاثة فأكثر.","","تلميذ مفرد، وهي تدل على واحد.","تلميذات جمع مؤنث، فهي أكثر من اثنتين."]},
  {"q":"أي الكلمات الآتية مفرد مؤنث؟","o":["طالبان","طالبات","طالبةٌ","طلّاب"],"a":2,"why":"طالبةٌ تدل على واحدة فقط، فهي مفرد مؤنث، ونقول: هذه طالبة. أما طالبان فمثنى، وطالبات وطلّاب جمعان.","ow":["طالبان مثنى مذكر، وتدل على اثنين.","طالبات جمع مؤنث، وتدل على ثلاث فأكثر.","","طلّاب جمع مذكر، وتدل على ثلاثة فأكثر."]},
  {"q":"كلمة <b>طالباتٌ</b> اسم:","o":["جمع مؤنث","مثنى مذكر","مفرد مؤنث","جمع مذكر"],"a":0,"why":"طالباتٌ فيها ألف وتاء زائدتان على المفرد طالبة، وتدل على ثلاث طالبات فأكثر، فهي جمع مؤنث.","ow":["","مثنى المذكر مثل طالبان، وليس طالبات.","مفرد المؤنث هو طالبة وتدل على واحدة فقط.","جمع المذكر مثل طالبون أو طلاب، وليس طالبات."]},
  {"q":"الجمع يدل على:","o":["واحد","اثنين فقط","اثنتين فقط","ثلاثة فأكثر"],"a":3,"why":"الجمع هو الاسم الذي يدل على ثلاثة فأكثر، مثل معلّمون ومعلّمات وطلّاب. أما المفرد فواحد، والمثنى اثنان.","ow":["واحد هو المفرد، وليس الجمع.","اثنين فقط هو المثنى، وليس الجمع.","اثنتين فقط هو مثنى المؤنث، وليس الجمع.",""]},
  {"q":"المثنى يدل على:","o":["اثنين أو اثنتين","واحد","ثلاثة فأكثر","خمسة فقط"],"a":0,"why":"المثنى هو الاسم الذي يدل على اثنين أو اثنتين، ويُصنع بزيادة ألف ونون على المفرد.","ow":["","واحد هو المفرد، وليس المثنى.","ثلاثة فأكثر هو الجمع، وليس المثنى.","خمسة فقط ليس تقسيمًا في الدرس، فالجمع يبدأ من ثلاثة."]},
  {"q":"كلمة <b>كتابان</b> اسم:","o":["جمع مذكر","مثنى مذكر","مثنى مؤنث","مفرد مؤنث"],"a":1,"why":"كتابان فيها ألف ونون زائدتان على المفرد كتاب، وكتاب مذكر، فهي مثنى مذكر وتدل على كتابين.","ow":["جمع المذكر مثل معلمون أو طلاب وهو لأكثر من اثنين، وكتابان لاثنين.","","مثنى المؤنث مثل مسطرتان، وكتاب مذكر وليس مؤنثًا.","كتابان تدل على اثنين وليست مفردة."]},
  {"q":"كلمة <b>مسطرتان</b> اسم:","o":["مفرد مؤنث","جمع مؤنث","مثنى مؤنث","مثنى مذكر"],"a":2,"why":"مسطرتان فيها ألف ونون زائدتان على المفرد مسطرة، وهي تدل على مسطرتين، فهي مثنى. ومسطرة مؤنث، فنقول: هذه مسطرة.","ow":["مفرد المؤنث هو مسطرة، وليس مسطرتان.","جمع المؤنث مثل مسطرات، وهو لثلاث فأكثر.","","مثنى المذكر مثل قلمان، ومسطرة مؤنث."]},
  {"q":"مفرد كلمة <b>طلّاب</b> هو:","o":["طالبة","طالبان","طلبة","طالب"],"a":3,"why":"طلّاب جمع، ومفرده طالب، وهي من الجموع التي يتغير شكل مفردها، فلا يكون الجمع بزيادة فقط.","ow":["طالبة مفرد مؤنث، ومفرد طلاب مذكر.","طالبان مثنى، وليس مفرد.","طلبة جمع آخر للطالب، وليست المفرد.",""]},
  {"q":"العبارة: نقول (هذه) عن الاسم المؤنث.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالاسم المؤنث نقول عنه هذه، مثل: هذه مسطرة، والمذكر نقول عنه هذا.","ow":["","العبارة صحيحة، فهذه تشير إلى المؤنث."]},
  {"q":"العبارة: المفرد ما دلّ على اثنين.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، لأن المفرد ما دلّ على واحد أو واحدة، أما ما دلّ على اثنين فهو المثنى.","ow":["المفرد يدل على واحد أو واحدة، وهو ليس على اثنين.",""]},
  {"q":"العبارة: <b>معلِّمون</b> جمع مذكر.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمعلِّمون فيها واو ونون زائدتان على المفرد معلِّم، وتدل على ثلاثة معلمين فأكثر.","ow":["","العبارة صحيحة، فمعلمون جمع مذكر سالم."]},
  {"q":"العبارة: الجمع يبدأ من اثنين.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ لأن الجمع يبدأ من ثلاثة فأكثر. أما الاسم الذي يدل على اثنين فهو المثنى مثل كتابان ومعلمان.","ow":["العبارة غير صحيحة، فالجمع لا يبدأ من اثنين بل من ثلاثة.",""]},
  {"q":"العبارة: <b>تلميذتان</b> مثنى مؤنث.","o":["صح","خطأ"],"a":0,"why":"تلميذة اسم مؤنث، وعند إضافة ألف ونون تصبح تلميذتان، وهي تدل على اثنتين، فهي مثنى مؤنث.","ow":["","العبارة صحيحة، فتلميذتان مثنى للمؤنث."]},
];
window.BANK['a5']['a5-1-4'] = [
  {"q":"يُكوَّن جمع المذكر السالم بزيادة على المفرد:","o":["ألف وتاء","ألف ونون","واو ونون أو ياء ونون","تاء فقط"],"a":2,"why":"جمع المذكر السالم يُكوَّن بزيادة واو ونون أو ياء ونون على مفرده، مثل: صادق ← صادقون وصادقين.","ow":["الألف والتاء تُزاد لجمع المؤنث السالم مثل صادقات.","الألف والنون تُزاد للمثنى مثل صادقان.","","التاء فقط لا تُكوّن جمع المذكر السالم."]},
  {"q":"جمع كلمة <b>صادق</b> جمع مذكر سالم هو:","o":["صادقات","صادقون","صدّاق","صادقان"],"a":1,"why":"صادق مفرد مذكر، وجمعه المذكر السالم صادقون بزيادة واو ونون، وتبقى حروف المفرد كما هي.","ow":["صادقات جمع مؤنث سالم.","","صدّاق ليست جمع صادق، بل كلمة مختلفة.","صادقان مثنى وليس جمعًا، فهو للاثنين."]},
  {"q":"جمع كلمة <b>مسلم</b> جمع مذكر سالم في حالة الجر هو:","o":["مسلمين","مسلمان","مسلمات","مسلمون"],"a":0,"why":"مسلم + ين = مسلمين، وهي جمع مذكر سالم في حالة الجر أو النصب، مثل: كرّمنا المسلمين، وفي حالة الرفع مسلمون.","ow":["","مسلمان مثنى، وليس جمعًا.","مسلمات جمع مؤنث سالم.","مسلمون جمع مذكر سالم لكنه في حالة الرفع، والمطلوب حالة الجر."]},
  {"q":"جمع كلمة <b>مؤمن</b> جمع مذكر سالم هو:","o":["مؤمنات","مؤمنان","مؤمنتان","مؤمنون"],"a":3,"why":"مؤمن + ون = مؤمنون، وهي جمع مذكر سالم لأننا زدنا واو ونون على المفرد دون تغيير حروفه.","ow":["مؤمنات جمع مؤنث سالم.","مؤمنان مثنى مذكر، وليس جمعًا.","مؤمنتان مثنى مؤنث، وليس جمع مذكر.",""]},
  {"q":"أي الكلمات الآتية جمع مذكر سالم مفرده لم يتغير؟","o":["متسابقون","ليمون","شياطين","مساكين"],"a":0,"why":"متسابقون هي متسابق + ون، ومفرد متسابق باقٍ سليمًا فهي جمع مذكر سالم. أما ليمون فاسم مفرد، ومساكين وشياطين جمعا تكسير.","ow":["","ليمون اسم مفرد ليس جمعًا.","شياطين تغيّر فيها مفرد شيطان، فهي جمع تكسير.","مساكين تغيّر فيها مفرد مسكين، فهي جمع تكسير."]},
  {"q":"سُمّي جمع المذكر السالم سالمًا لأن:","o":["لا يتغير فيه آخر الكلمة","مفرده لم يتغير","له ثلاثة أحرف","لا يدل على جمع"],"a":1,"why":"سمّي سالمًا لأن صورة المفرد لا تتغير، فنُبقي حروفه كما هي ونضيف واو ونون أو ياء ونون فقط.","ow":["آخر الكلمة يتغير فعلًا بين الواو والياء بحسب الحالة، لكن السلامة تعني بقاء صورة المفرد.","","عدد الأحرف ليس هو سبب التسمية.","هو جمع ويدل على أكثر من اثنين."]},
  {"q":"كلمة <b>ليمون</b> ليست جمع مذكر سالم لأنها:","o":["فعل","جمع تكسير","اسم مفرد","مثنى"],"a":2,"why":"ليمون اسم مفرد ينتهي بواو ونون، ولا يوجد مفرد اسمه ليم زيدت عليه الواو والنون، فلا يكون جمعًا.","ow":["ليمون اسم وليست فعلًا.","ليمون ليست جمع تكسير، بل هي مفرد.","","ليمون ليست مثنى، فالمثنى ينتهي بألف ونون."]},
  {"q":"كلمة <b>تُرحمون</b> ليست جمع مذكر سالم لأنها:","o":["اسم مفرد","جمع تكسير","مثنى","فعل مضارع"],"a":3,"why":"تُرحمون فعل مضارع يدل على حدث هو الرحمة، وجمع المذكر السالم لا يكون إلا في الأسماء، فنفرّق بالمعنى.","ow":["تُرحمون ليست اسمًا، بل تدل على حدث.","تُرحمون ليست جمعًا للتكسير، لأنها فعل.","تُرحمون ليست مثنى، لأنها تنتهي بواو ونون.",""]},
  {"q":"كلمة <b>مساكين</b> ليست جمع مذكر سالم لأن:","o":["مفردها مسكين وتغيّرت صورته","مفردها لم يتغير","ليس فيها ياء","فيها ألف"],"a":0,"why":"مساكين مفردها مسكين، وعند الجمع تغيّرت صورته فصارت مساكين، فهي جمع تكسير وليست جمع مذكر سالم.","ow":["","في جمع المذكر السالم يبقى المفرد كما هو دون تغيير، وهنا تغيّر.","وجود الياء والنون ليس كافيًا، فلا بد أن يبقى شكل المفرد سليمًا.","الألف في مساكين دليل على تغيّر المفرد، وليس جمعًا سالمًا."]},
  {"q":"جمع <b>شيطان</b> هو <b>شياطين</b>، ونوعه:","o":["مذكر سالم","تكسير","مؤنث سالم","مثنى"],"a":1,"why":"شياطين جمع شيطان، وقد تغيّرت صورة المفرد، فهي جمع تكسير. أما المفرد السليم مثل متسابق فيصبح متسابقون.","ow":["جمع المذكر السالم يبقى المفرد فيه سليمًا، وهنا تغيّر.","","جمع المؤنث السالم ينتهي بألف وتاء، وشياطين لا تنتهي بها.","المثنى يدل على اثنين وينتهي بألف ونون، وشياطين تدل على أكثر من اثنين."]},
  {"q":"أي الكلمات الآتية ليست جمع مذكر سالم؟","o":["صابرين","تائبون","ليمون","متسابقين"],"a":2,"why":"ليمون اسم مفرد وليس جمعًا، فليس له مفرد زدنا عليه الواو والنون. أما صابرين وتائبون ومتسابقين فجموع مذكر سالمة.","ow":["صابرين جمع مذكر سالم من صابر + ين.","تائبون جمع مذكر سالم من تائب + ون.","","متسابقين جمع مذكر سالم من متسابق + ين."]},
  {"q":"جمع <b>تائب</b> جمع مذكر سالم في حالة الرفع:","o":["تائبان","تائبات","تائبتان","تائبون"],"a":3,"why":"تائب + ون = تائبون في حالة الرفع، وهي جمع مذكر سالم تبقى فيها حروف المفرد كما هي.","ow":["تائبان مثنى، وليس جمعًا.","تائبات جمع مؤنث سالم.","تائبتان مثنى مؤنث.",""]},
  {"q":"يدل جمع المذكر السالم على:","o":["أكثر من اثنين","اثنين فقط","واحد","اثنتين"],"a":0,"why":"جمع المذكر السالم يدل على أكثر من اثنين، أي ثلاثة فأكثر، مثل: مؤمنون ومسلمون. أما الاثنان فيسميان مثنى.","ow":["","اثنين فقط هو المثنى.","واحد هو المفرد.","اثنتين هو مثنى المؤنث."]},
  {"q":"الكلمة <b>صابرات</b> هي جمع:","o":["مذكر سالم","مؤنث سالم","تكسير","مثنى"],"a":1,"why":"صابرات فيها ألف وتاء زائدتان على المفرد صابرة، فهي جمع مؤنث سالم. أما المذكر فصابرون.","ow":["جمع المذكر السالم ينتهي بواو ونون أو ياء ونون، وصابرات ليست كذلك.","","صابرات لم يتغير فيها المفرد صابرة، فليست جمع تكسير.","المثنى ينتهي بألف ونون، وصابرات تدل على أكثر من اثنتين."]},
  {"q":"عند جمع <b>مهندس</b> جمع مذكر سالم، فإن المفرد:","o":["يتغير","يُحذف منه حرف","يبقى سليمًا","يتحول إلى مثنى"],"a":2,"why":"عند جمع مهندس جمع مذكر سالم يبقى المفرد سليمًا فنقول مهندسون، ولا يتغير شكله، لأن هذا معنى سالم.","ow":["المفرد لا يتغير في جمع المذكر السالم.","لا يُحذف حرف من المفرد، فكلها تبقى.","","لا يتحول المفرد إلى مثنى، بل إلى جمع."]},
  {"q":"العبارة: <b>متسابقون</b> جمع مذكر سالم مفرده متسابق.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمتسابقون جمع مذكر سالم، وهو متسابق + ون، ومفرده لم يتغير بل بقيت حروفه كاملة.","ow":["","العبارة صحيحة، فمتسابقون مأخوذة من متسابق بزيادة واو ونون."]},
  {"q":"العبارة: <b>ليمون</b> جمع مذكر سالم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فليمون اسم مفرد، ولا توجد كلمة ليم تُجمع فيه بزيادة واو ونون، لذا ليس جمع مذكر سالم.","ow":["ليمون اسم مفرد وليس جمعًا، وإن كانت تنتهي بواو ونون.",""]},
  {"q":"العبارة: <b>مساكين</b> جمع تكسير.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمساكين جمع مسكين، وقد تغيّرت صورة المفرد عند الجمع، فهي جمع تكسير.","ow":["","مساكين جمع تكسير فعلًا لأن مفردها تغيّر."]},
  {"q":"العبارة: <b>تُرحمون</b> اسم جمع مذكر سالم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فتُرحمون فعل مضارع وليست اسمًا، وجمع المذكر السالم لا يكون إلا في الأسماء.","ow":["ترحمون ليست اسمًا حتى تكون جمعًا، بل هي فعل.",""]},
  {"q":"العبارة: تُزاد ياء ونون على المفرد في بعض حالات جمع المذكر السالم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فتُزاد واو ونون في حالة الرفع مثل مسلمون، وتُزاد ياء ونون في النصب والجر مثل مسلمين.","ow":["","العبارة صحيحة، فالياء والنون تُزاد في جمع المذكر السالم مثل صابرين."]},
];
window.BANK['a5']['a5-1-5'] = [
  {"q":"الأفعال الخمسة تبدأ بأحد حروف:","o":["(أنيت)","(سألتمونيها)","(نون الوقاية)","(الواو والفاء)"],"a":0,"why":"الفعل المضارع يبدأ بأحد حروف أنيت وهي: الهمزة والنون والياء والتاء، مثل: ألعب ونلعب ويلعب وتلعب. والأفعال الخمسة لا بد أن تكون مضارعة.","ow":["","حروف سألتمونيها هي حروف الزيادة، وليست حروف المضارعة.","نون الوقاية ليست حرفًا من حروف المضارعة.","الواو والفاء حرفا عطف، ولا تبدأ بهما الأفعال المضارعة."]},
  {"q":"أي الأفعال الآتية يُعدّ من الأفعال الخمسة؟","o":["يلعبُ","لعبوا","يلعبان","العبْ"],"a":2,"why":"يلعبان فعل مضارع يبدأ بالياء، واتصلت به ألف الاثنين لأن الفاعل اثنان، فهو من الأفعال الخمسة. أما يلعبُ فمفرد، ولعبوا ماضٍ، والعبْ أمر.","ow":["يلعبُ فعل مضارع لكن لم يتصل به ضمير.","لعبوا فعل ماضٍ، والأفعال الخمسة لا بد أن تكون مضارعة.","","العبْ فعل أمر وليس مضارعًا."]},
  {"q":"الفعل <b>تلعبين</b> اتصلت به:","o":["ألف الاثنين","واو الجماعة","ياء المخاطبة","نون النسوة"],"a":2,"why":"تلعبين فعل مضارع يبدأ بالتاء، والياء والنون في آخره تدلان على أن الفاعل مخاطبة مؤنثة، فاتصلت به ياء المخاطبة.","ow":["ألف الاثنين تكون في مثل تلعبان.","واو الجماعة تكون في مثل تلعبون.","","نون النسوة تدخل على الفعل مثل تلعبن، وليست من الأفعال الخمسة."]},
  {"q":"الفعل <b>يكتبون</b> اتصلت به:","o":["واو الجماعة","ألف الاثنين","ياء المخاطبة","تاء التأنيث"],"a":0,"why":"يكتبون فعل مضارع، والفاعل جماعة، فاتصلت به واو الجماعة والنون. فهو من الأفعال الخمسة.","ow":["","ألف الاثنين تكون في مثل يكتبان.","ياء المخاطبة تكون في مثل تكتبين.","تاء التأنيث ليست ما اتصل بيكتبون."]},
  {"q":"الفعل <b>تدرسان</b> اتصلت به:","o":["ياء المخاطبة","ألف الاثنين","واو الجماعة","لا شيء"],"a":1,"why":"تدرسان فعل مضارع يبدأ بالتاء، واتصلت به ألف الاثنين لأن الفاعل اثنان، فهو من الأفعال الخمسة.","ow":["ياء المخاطبة تكون في مثل تدرسين.","","واو الجماعة تكون في مثل تدرسون.","اتصل بالفعل ألف الاثنين، فلا تقل إنه لم يتصل به شيء."]},
  {"q":"الفعل <b>كتبوا</b> ليس من الأفعال الخمسة لأنه:","o":["فعل أمر","اسم","فعل ماضٍ","حرف"],"a":2,"why":"كتبوا فعل ماضٍ لأنه يدل على حدث انتهى، والأفعال الخمسة لا بد أن تكون مضارعة، فلا يكون من الأفعال الخمسة.","ow":["كتبوا ليس فعل أمر، فالأمر هو اكتبوا.","كتبوا ليست اسمًا، فهي تدل على حدث.","","كتبوا ليست حرفًا، فهي تدل على حدث."]},
  {"q":"الفعل <b>اكتبوا</b> ليس من الأفعال الخمسة لأنه:","o":["فعل ماضٍ","اسم","مضارع","فعل أمر"],"a":3,"why":"اكتبوا فعل أمر لأنه يطلب حدوث الفعل، والأفعال الخمسة لا بد أن تكون مضارعة تبدأ بأحد حروف أنيت، فليس منها.","ow":["اكتبوا ليست فعلًا ماضيًا، فالماضي هو كتبوا.","اكتبوا ليست اسمًا، فهي تدل على حدث.","اكتبوا ليست مضارعة، فلا تبدأ بحرف من حروف أنيت.",""]},
  {"q":"الفعل الذي من الأفعال الخمسة في: <b>المخترعون يعملون بجدّ</b>","o":["المخترعون","يعملون","بجدّ","لا يوجد"],"a":1,"why":"يعملون فعل مضارع يبدأ بالياء، واتصلت به واو الجماعة لأن المخترعون جماعة، فهو من الأفعال الخمسة.","ow":["المخترعون اسم مرفوع، وهو فاعل الفعل.","","بجدّ اسم مجرور بعد حرف الجر، وليس فعلًا.","يوجد فعل هو يعملون."]},
  {"q":"الفعل الذي من الأفعال الخمسة في: <b>أنتم تتقنون عملكم</b>","o":["تتقنون","أنتم","عملكم","لا يوجد"],"a":0,"why":"تتقنون فعل مضارع يبدأ بالتاء، واتصلت به واو الجماعة لأن الفاعل أنتم، فهو من الأفعال الخمسة.","ow":["","أنتم ضمير منفصل، وليس فعلًا.","عملكم اسم، وليس فعلًا.","يوجد فعل هو تتقنون."]},
  {"q":"يصبح الفعل <b>يدرس</b> مع واو الجماعة:","o":["يدرسان","يدرسين","يدرسون","درسوا"],"a":2,"why":"نضيف إلى المضارع يدرس واو الجماعة والنون فيصبح يدرسون، لأن الفاعل جماعة. وهذه الصيغة من الأفعال الخمسة.","ow":["يدرسان فيها ألف الاثنين، وهي للاثنين.","يدرسين ليست صيغة صحيحة، فياء المخاطبة تكون مع التاء: تدرسين.","","درسوا فعل ماضٍ، والمطلوب المضارع."]},
  {"q":"يصبح الفعل <b>تحب</b> مع ياء المخاطبة:","o":["تحبون","تحبان","تحبّ","تحبين"],"a":3,"why":"نضيف إلى المضارع تحب ياء المخاطبة ونونًا فتصبح تحبين، لأن الفاعل مخاطبة مؤنثة. وهذه الصيغة من الأفعال الخمسة.","ow":["تحبون فيها واو الجماعة، وهي للجماعة.","تحبان فيها ألف الاثنين، وهي للاثنين.","تحبّ فعل مضارع مفرد لم يتصل به ضمير.",""]},
  {"q":"أي الأفعال الآتية <b>ليس</b> من الأفعال الخمسة؟","o":["يكتبُ","يكتبان","تكتبون","تكتبين"],"a":0,"why":"يكتبُ فعل مضارع مفرد، لم تتصل به ألف الاثنين ولا واو الجماعة ولا ياء المخاطبة، فليس من الأفعال الخمسة.","ow":["","يكتبان فيها ألف الاثنين، فهي من الأفعال الخمسة.","تكتبون فيها واو الجماعة، فهي من الأفعال الخمسة.","تكتبين فيها ياء المخاطبة، فهي من الأفعال الخمسة."]},
  {"q":"عدد الضمائر التي تتصل بالأفعال الخمسة:","o":["اثنان","ثلاثة","أربعة","خمسة"],"a":1,"why":"تتصل بالأفعال الخمسة ثلاثة ضمائر هي: ألف الاثنين وواو الجماعة وياء المخاطبة. وتنتج منها خمس صيغ لذلك سميت الأفعال الخمسة.","ow":["الضمائر ثلاثة وليست اثنين، فنسينا ضميرًا منها.","","الضمائر ثلاثة وليست أربعة.","الخمسة هي عدد الصيغ، وليس عدد الضمائر."]},
  {"q":"أي الجمل الآتية فيها فعل مضارع من الأفعال الخمسة؟","o":["كتبَ الولدُ","الطالبون مجتهدون","اجتهدْ يا ولدُ","الطلابُ يجتهدون"],"a":3,"why":"يجتهدون فعل مضارع يبدأ بالياء، واتصلت به واو الجماعة لأن الطلاب جماعة، فهو من الأفعال الخمسة.","ow":["كتبَ فعل ماضٍ، فلا يكون من الأفعال الخمسة.","مجتهدون اسم وليس فعلًا.","اجتهدْ فعل أمر وليس مضارعًا.",""]},
  {"q":"الفعل <b>يتعاقبان</b> اتصلت به:","o":["ألف الاثنين","ياء المخاطبة","واو الجماعة","لا شيء"],"a":0,"why":"يتعاقبان فعل مضارع يبدأ بالياء، واتصلت به ألف الاثنين لأن الفاعل اثنان، فهو من الأفعال الخمسة التي نعرفها بهذه الألف.","ow":["","ياء المخاطبة تكون في مثل تتعاقبين.","واو الجماعة تكون في مثل يتعاقبون.","اتصل بالفعل ألف الاثنين، فلا يصح أنه لم يتصل به شيء."]},
  {"q":"العبارة: الأفعال الخمسة كلها أفعال مضارعة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأفعال الخمسة لا بد أن تكون أفعالًا مضارعة تبدأ بأحد حروف أنيت، ثم يتصل بها ألف الاثنين أو واو الجماعة أو ياء المخاطبة.","ow":["","العبارة صحيحة، فالفعل الماضي والأمر لا يكونان من الأفعال الخمسة."]},
  {"q":"العبارة: <b>يلعبُ</b> من الأفعال الخمسة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فيلعبُ فعل مضارع مفرد، لم تتصل به ألف الاثنين ولا واو الجماعة ولا ياء المخاطبة، فليس من الأفعال الخمسة.","ow":["يلعبُ مفرد، والأفعال الخمسة تتصل بها الضمائر الثلاثة، وهذا لم تتصل به.",""]},
  {"q":"العبارة: <b>تعملين</b> من الأفعال الخمسة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فتعملين فعل مضارع يبدأ بالتاء، واتصلت به ياء المخاطبة، فهو من الأفعال الخمسة.","ow":["","العبارة صحيحة، فتعملين فيها ياء المخاطبة."]},
  {"q":"العبارة: <b>كتبوا</b> من الأفعال الخمسة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، لأن كتبوا فعل ماضٍ، والأفعال الخمسة لا بد أن تكون مضارعة، حتى لو اتصلت بها واو الجماعة.","ow":["كتبوا فعل ماضٍ فلا تكون من الأفعال الخمسة، رغم وجود واو الجماعة فيها.",""]},
  {"q":"العبارة: الفعل الذي يبدأ بحرف الباء يكون من الأفعال الخمسة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالفعل لا يكون من الأفعال الخمسة بحرف أول معيّن مثل الباء، بل لا بد أن يكون مضارعًا يبدأ بأحد حروف أنيت: الهمزة والنون والياء والتاء.","ow":["الأفعال الخمسة تبدأ بأحد حروف أنيت، والباء ليست منها.",""]},
];
window.BANK['a5']['a5-1-6'] = [
  {"q":"عدد أنواع الجموع:","o":["اثنان","أربعة","ثلاثة","خمسة"],"a":2,"why":"الجموع ثلاثة أنواع: جمع المذكر السالم، وجمع المؤنث السالم، وجمع التكسير. وكل نوع له طريقته في التكوين.","ow":["الأنواع ثلاثة وليست اثنين، فقد نسيت نوعًا منها.","الأنواع ثلاثة وليست أربعة.","","الأنواع ثلاثة وليست خمسة."]},
  {"q":"نوع الجمع في كلمة <b>معلِّمات</b>:","o":["مؤنث سالم","مذكر سالم","تكسير","مثنى"],"a":0,"why":"معلِّمات هي معلِّمة + ات، فزيادة الألف والتاء على المفرد تجعلها جمع مؤنث سالم، وصورة المفرد باقية.","ow":["","جمع المذكر السالم ينتهي بواو ونون أو ياء ونون.","جمع التكسير تتغير فيه صورة المفرد، وهنا بقيت معلِّمة كاملة.","المثنى ينتهي بألف ونون، ومعلِّمات تدل على أكثر من اثنتين."]},
  {"q":"نوع الجمع في كلمة <b>مهندسين</b>:","o":["تكسير","مذكر سالم","مؤنث سالم","مفرد"],"a":1,"why":"مهندسين هي مهندس + ين، وصورة المفرد لم تتغير، فهي جمع مذكر سالم في حالة النصب أو الجر.","ow":["جمع التكسير تتغير فيه صورة المفرد، وهنا بقيت كلمة مهندس سليمة.","","جمع المؤنث السالم ينتهي بألف وتاء.","مهندسين ليست مفردة، فهي تدل على أكثر من اثنين."]},
  {"q":"نوع الجمع في كلمة <b>ألوان</b>:","o":["مذكر سالم","مؤنث سالم","مثنى","تكسير"],"a":3,"why":"ألوان جمع مفرده لون، وقد زيدت فيها ألف في أول الكلمة وفي آخرها فتغيّرت صورة المفرد، فهي جمع تكسير.","ow":["جمع المذكر السالم ينتهي بواو ونون أو ياء ونون، وألوان لا تنتهي بها.","جمع المؤنث السالم ينتهي بألف وتاء، وألوان لا تنتهي بها.","المثنى ينتهي بألف ونون ويدل على اثنين، وألوان أكثر من اثنين.",""]},
  {"q":"نوع الجمع في كلمة <b>زهور</b>:","o":["تكسير","مؤنث سالم","مذكر سالم","مثنى"],"a":0,"why":"زهور مفردها زهرة، وقد تغيرت صورة المفرد عند الجمع، فهي جمع تكسير وليست مؤنثًا سالمًا.","ow":["","جمع المؤنث السالم ينتهي بألف وتاء مثل زهرات، وزهور لا تنتهي بها.","جمع المذكر السالم ينتهي بواو ونون أو ياء ونون، وزهور ليست كذلك.","المثنى ينتهي بألف ونون ويدل على اثنين."]},
  {"q":"نوع الجمع في كلمة <b>الصادقون</b>:","o":["تكسير","مؤنث سالم","مذكر سالم","مثنى"],"a":2,"why":"الصادقون هي الصادق + ون، وصورة المفرد لم تتغير، فهي جمع مذكر سالم، وتنتهي بواو ونون.","ow":["جمع التكسير تتغير فيه صورة المفرد، وهنا بقيت كلمة صادق سليمة.","جمع المؤنث السالم ينتهي بألف وتاء.","","المثنى ينتهي بألف ونون، والصادقون أكثر من اثنين."]},
  {"q":"نوع الجمع في كلمة <b>الخضراوات</b>:","o":["تكسير","مؤنث سالم","مذكر سالم","مثنى"],"a":1,"why":"الخضراوات هي جمع خضراء، وتنتهي بألف وتاء، فهي جمع مؤنث سالم يدل على أكثر من اثنتين.","ow":["جمع التكسير تتغير فيه صورة المفرد، وهنا زِيدت ألف وتاء فقط.","","جمع المذكر السالم ينتهي بواو ونون أو ياء ونون.","المثنى ينتهي بألف ونون."]},
  {"q":"جمع المؤنث السالم من كلمة <b>طبيبة</b>:","o":["طبيبون","أطباء","طبيبان","طبيبات"],"a":3,"why":"نكوّن جمع المؤنث السالم بزيادة ألف وتاء على المفرد، فطبيبة تصبح طبيبات، وتدل على أكثر من اثنتين.","ow":["طبيبون جمع مذكر سالم، وطبيبة مؤنث.","أطباء جمع تكسير لكلمة طبيب، وليس جمع المؤنث السالم.","طبيبان مثنى مذكر، وليس جمعًا.",""]},
  {"q":"جمع كلمة <b>رجل</b> جمع تكسير:","o":["رجال","رجلان","رجلون","رجلات"],"a":0,"why":"رجل جمعها رجال، وقد زيدت الألف على المفرد فتغيرت صورته، وهذه إحدى طرق التكسير الثلاث.","ow":["","رجلان مثنى وليس جمعًا.","رجلون ليست جمعًا صحيحًا لكلمة رجل.","رجلات ليست جمعًا صحيحًا لكلمة رجل."]},
  {"q":"جمع كلمة <b>أسَد</b> جمع تكسير:","o":["أسدون","أُسْد","أسدات","أسدان"],"a":1,"why":"أسَد جمعها أُسْد، فقد تغيّر ضبط الكلمة فقط دون زيادة أو نقصان، وهذا من جمع التكسير.","ow":["أسدون ليست جمعًا صحيحًا لكلمة أسد.","","أسدات ليست جمعًا صحيحًا لكلمة أسد.","أسدان مثنى وليس جمعًا."]},
  {"q":"تكسير <b>كتاب</b> هو <b>كُتُب</b>، والطريقة:","o":["زيادة حرف","تغيير في الضبط فقط","نقصان حرف","زيادة ألف ونون"],"a":2,"why":"كتاب تصبح كُتُب عند التكسير، وقد حُذفت الألف من المفرد، فالطريقة هي نقصان حرف، وهي إحدى طرق جمع التكسير.","ow":["في كتاب وكتب لم يُزَد حرف، بل نقص حرف.","لم يتغير الضبط فقط، بل حُذف حرف من الكلمة.","","زيادة الألف والنون تجعل الاسم مثنى، وليست من طرق التكسير."]},
  {"q":"طرق جمع التكسير هي:","o":["زيادة واو ونون","زيادة ألف وتاء","زيادة ياء ونون","زيادة حرف أو نقصانه أو تغيير الضبط"],"a":3,"why":"جمع التكسير تتغير فيه صورة المفرد بإحدى طرق ثلاث: زيادة حرف مثل رجال، أو نقصان حرف مثل كُتُب، أو تغيير الضبط مثل أُسْد.","ow":["زيادة واو ونون طريقة لجمع المذكر السالم.","زيادة ألف وتاء طريقة لجمع المؤنث السالم.","زيادة ياء ونون طريقة لجمع المذكر السالم.",""]},
  {"q":"الجمع الذي تتغير فيه صورة المفرد هو جمع:","o":["التكسير","المذكر السالم","المؤنث السالم","المثنى"],"a":0,"why":"جمع التكسير هو الذي تتغير فيه صورة المفرد، أي نكسّرها، مثل: رجل ← رجال، كتاب ← كُتُب.","ow":["","جمع المذكر السالم يبقى فيه المفرد سالمًا.","جمع المؤنث السالم يبقى فيه المفرد سالمًا.","المثنى يدل على اثنين وليس من أنواع الجموع."]},
  {"q":"جمع المذكر السالم يدل على أكثر من:","o":["واحد","اثنين","ثلاثة","أربعة"],"a":1,"why":"جمع المذكر السالم هو ما دل على أكثر من اثنين، أي ثلاثة فأكثر، أما الاثنان فمثنى.","ow":["واحد هو المفرد، وليس الجمع.","","الجمع أكثر من اثنين، فلا يشترط أكثر من ثلاثة.","ثلاثة داخلة في الجمع، فالجمع أكثر من اثنين."]},
  {"q":"يدل جمع المؤنث السالم على أكثر من:","o":["واحدة","ثلاث","اثنتين","خمس"],"a":2,"why":"جمع المؤنث السالم هو ما دل على أكثر من اثنتين، أي ثلاث فأكثر، وتكوّنه بزيادة ألف وتاء.","ow":["واحدة هي المفرد المؤنث.","ثلاث داخلة في الجمع، فالجمع أكثر من اثنتين.","","خمس ليست شرطًا، فالجمع يبدأ من ثلاث."]},
  {"q":"العبارة: <b>مهندسون</b> جمع مذكر سالم.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمهندسون هي مهندس + ون، وصورة المفرد باقية، فهي جمع مذكر سالم ينتهي بواو ونون.","ow":["","العبارة صحيحة، فمهندسون ينتهي بواو ونون."]},
  {"q":"العبارة: <b>رجال</b> جمع مؤنث سالم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فرجال جمع مفرده رجل، وقد تغيرت صورته بزيادة الألف، فهو جمع تكسير وليس جمع مؤنث سالم.","ow":["رجال لا تنتهي بألف وتاء، ولا يصح أن تكون جمع مؤنث سالم.",""]},
  {"q":"العبارة: جمع المؤنث السالم يكون بزيادة ألف وتاء على المفرد.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجمع المؤنث السالم يكوّن بزيادة ألف وتاء على المفرد، مثل: طبيبة ← طبيبات، ومعلمة ← معلمات.","ow":["","العبارة صحيحة، فهذه قاعدة جمع المؤنث السالم."]},
  {"q":"العبارة: <b>حكايات</b> جمع تكسير.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فحكايات هي حكاية + ات، وصورة المفرد لم تتغير، فهي جمع مؤنث سالم وليست جمع تكسير.","ow":["حكايات بقيت فيها كلمة حكاية كاملة، فهي جمع مؤنث سالم.",""]},
  {"q":"العبارة: تغيّر صورة المفرد يدل على جمع التكسير.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجمع التكسير هو الذي تتغير فيه صورة المفرد بزيادة حرف أو نقصانه أو تغيير الضبط.","ow":["","العبارة صحيحة، فتغيّر صورة المفرد هو سبب تسميته تكسيرًا."]},
];
window.BANK['a5']['a5-1-7'] = [
  {"q":"تُكتب همزة القطع في أول الكلمة على صورة:","o":["(ا) دون همزة","(أ) أو (إ)","(ؤ)","(ئ)"],"a":1,"why":"همزة القطع تُكتب في أول الكلمة على ألف فوقها همزة أ أو تحتها همزة إ، مثل: أحمد وإخراج، لأنها تُنطق دائمًا.","ow":["الألف دون همزة هي صورة همزة الوصل.","","الهمزة على الواو ؤ تأتي في وسط الكلمة وليس في أول الكلمة.","الهمزة على الياء ئ تأتي في وسط الكلمة وليس في أول الكلمة."]},
  {"q":"تُكتب همزة الوصل على صورة:","o":["(أ)","(إ)","(ا) دون همزة","(ء)"],"a":2,"why":"همزة الوصل تُكتب ألفًا دون همزة فوقها أو تحتها، لأنها لا تُنطق عند وصلها بما قبلها، مثل: ابن واسم.","ow":["أ تُكتب بها همزة القطع.","إ تُكتب بها همزة القطع.","","الهمزة بصورتها المنفصلة ليست صورة همزة الوصل."]},
  {"q":"نوع الهمزة في كلمة <b>أخرجَ</b>:","o":["قطع","وصل","متوسطة","مربوطة"],"a":0,"why":"أخرجَ همزتها تُنطق دائمًا حتى لو وصلناها بكلمة قبلها، وتُكتب أ فوق الألف، فهي همزة قطع.","ow":["","لو كانت وصلًا لاختفت عند الوصل وكُتبت ألفًا دون همزة.","المتوسطة تكون في وسط الكلمة، وهذه في أولها.","المربوطة من أنواع التاء، وليست همزة."]},
  {"q":"نوع الهمزة في كلمة <b>اسمٌ</b>:","o":["قطع","متطرفة","وصل","مفتوحة"],"a":2,"why":"اسمٌ همزتها همزة وصل، لأنها تُكتب ألفًا دون همزة، ولا تُنطق إذا وصلناها بما قبلها: هذا اسمُ أحمد.","ow":["لو كانت قطعًا لُكتبت أ أو إ، ولنُطقت دائمًا.","المتطرفة تكون في آخر الكلمة، وهذه في أولها.","","المفتوحة نوع من أنواع التاء، وليست همزة."]},
  {"q":"نوع الهمزة في كلمة <b>انطلقَ</b>:","o":["قطع","وصل","تاء","متوسطة"],"a":1,"why":"انطلقَ همزتها همزة وصل، تُكتب ألفًا دون همزة، ولا تُنطق إذا وصلناها بما قبلها، مثل: ابن واسم واستعان.","ow":["لو كانت قطعًا لُكتبت أ أو إ، ولنُطقت دائمًا.","","التاء ليست همزة، وكلمة انطلق همزتها في أولها.","ليست متوسطة، بل في أول الكلمة."]},
  {"q":"نوع الهمزة في كلمة <b>إيمانٌ</b>:","o":["وصل","تاء","مربوطة","قطع"],"a":3,"why":"إيمانٌ همزتها همزة قطع، تُكتب إ تحت الألف، وتُنطق دائمًا حتى عند وصلها بما قبلها: هذا إيمانٌ.","ow":["لو كانت وصلًا لُكتبت ألفًا دون همزة، ولاختفت عند الوصل.","التاء ليست همزة، وهذا السؤال عن نوع الهمزة.","المربوطة نوع من أنواع التاء، وليست همزة.",""]},
  {"q":"أي الكلمات الآتية همزتها همزة وصل؟","o":["أكلَ","ابنٌ","إيمان","أملٌ"],"a":1,"why":"ابنٌ همزتها همزة وصل، فتُكتب ألفًا دون همزة، وتختفي عند وصلها بما قبلها. أما أكلَ وإيمان وأملٌ فهمزاتها همزات قطع.","ow":["أكلَ همزتها قطع، لأنها تُكتب أ وتُنطق دائمًا.","","إيمان همزتها قطع، لأنها تُكتب إ وتُنطق دائمًا.","أملٌ همزتها قطع، لأنها تُكتب أ وتُنطق دائمًا."]},
  {"q":"أي الكلمات الآتية همزتها همزة قطع؟","o":["استعانَ","ابنٌ","اسمٌ","إخراجٌ"],"a":3,"why":"إخراجٌ همزتها همزة قطع، تُكتب إ تحت الألف وتُنطق دائمًا. أما استعان وابن واسم فهمزاتها همزات وصل.","ow":["استعانَ همزتها وصل، فتُكتب ألفًا دون همزة.","ابنٌ همزتها وصل، فتُكتب ألفًا دون همزة.","اسمٌ همزتها وصل، فتُكتب ألفًا دون همزة.",""]},
  {"q":"همزة الوصل هي التي:","o":["تُنطق في ابتداء الكلام ولا تُنطق عند وصلها بما قبلها","تُنطق دائمًا","تُكتب أ أو إ","تكون في آخر الكلمة"],"a":0,"why":"همزة الوصل هي التي تُنطق إذا بدأنا بها الكلام، ولا تُنطق إذا وصلناها بما قبلها، وتُكتب ألفًا دون همزة.","ow":["","همزة القطع هي التي تُنطق دائمًا.","هذه صفة همزة القطع وليست الوصل.","همزة الوصل تكون في أول الكلمة وليس في آخرها."]},
  {"q":"التاء في كلمة <b>قصةٌ</b> تسمى:","o":["مفتوحة","مربوطة","مبسوطة","همزة"],"a":1,"why":"قصةٌ تنتهي بتاء مربوطة، وهي التي تُنطق هاءً عند الوقف: قصه. وتأتي في آخر الأسماء المؤنثة غالبًا.","ow":["المفتوحة تُنطق تاءً عند الوقف مثل بيت.","","لا يوجد نوع اسمه المبسوطة، فالتاء إما مربوطة أو مفتوحة.","الهمزة ليست نوعًا من أنواع التاء."]},
  {"q":"التاء في كلمة <b>بنتٌ</b> تسمى:","o":["مربوطة","همزة","مفتوحة","ألفًا"],"a":2,"why":"بنتٌ تنتهي بتاء مفتوحة، تُنطق تاءً عند الوقف: بنت، وهي الأصل في الحرف المفتوح المكتوب بالنقطتين.","ow":["التاء المربوطة تُنطق هاءً عند الوقف مثل قصه.","الهمزة حرف آخر، وليست هي المقصودة.","","الألف حرف آخر، وليست هي التاء."]},
  {"q":"عند الوقف على كلمة <b>غرفةٌ</b> ننطق آخرها:","o":["تاءً","ألفًا","نونًا","هاءً"],"a":3,"why":"عند الوقف على غرفةٌ ننطق آخرها هاءً فنقول: غرفه، لأن التاء المربوطة تُنطق هاءً عند الوقف، أما التاء المفتوحة فتُنطق تاءً.","ow":["التاء المربوطة لا تُنطق تاءً عند الوقف بل هاءً.","التاء المربوطة لا تُنطق ألفًا.","التاء المربوطة لا تُنطق نونًا.",""]},
  {"q":"أي الكلمات الآتية فيها تاء مفتوحة؟","o":["قصةٌ","غرفةٌ","بيتٌ","مدرسةٌ"],"a":2,"why":"بيتٌ فيها تاء مفتوحة، لأنها تُنطق تاءً عند الوقف: بيت. أما قصة وغرفة ومدرسة فبتاء مربوطة تُنطق هاءً عند الوقف.","ow":["قصةٌ فيها تاء مربوطة تُنطق هاءً عند الوقف.","غرفةٌ فيها تاء مربوطة تُنطق هاءً عند الوقف.","","مدرسةٌ فيها تاء مربوطة تُنطق هاءً عند الوقف."]},
  {"q":"أي الكلمات الآتية فيها تاء مربوطة؟","o":["بنتٌ","بيتٌ","مدرسةٌ","وقتٌ"],"a":2,"why":"مدرسةٌ فيها تاء مربوطة، لأنها تُنطق هاءً عند الوقف: مدرسه. أما بنت وبيت ووقت فبتاء مفتوحة تُنطق تاءً.","ow":["بنتٌ فيها تاء مفتوحة، تُنطق تاءً عند الوقف.","بيتٌ فيها تاء مفتوحة، تُنطق تاءً عند الوقف.","","وقتٌ فيها تاء مفتوحة، تُنطق تاءً عند الوقف."]},
  {"q":"نختبر الهمزة في الكلمة هل هي وصل أو قطع بأن:","o":["نصلها بكلمة قبلها وننظر هل تُنطق","نعدّ حروفها","ننظر إلى آخرها","نضيف إليها تاءً"],"a":0,"why":"نصل الكلمة بكلمة قبلها وننظر: إن لم نسمع الهمزة فهي وصل، وإن سمعناها فهي قطع. مثل: هذا ابنُ أحمد، لا نسمع همزة ابن.","ow":["","عدّ الحروف لا يحدد نوع الهمزة.","آخر الكلمة لا يحدد نوع الهمزة في أولها.","إضافة التاء لا تفرّق بين الهمزتين."]},
  {"q":"العبارة: همزة القطع تُنطق في أول الكلام ووسطه.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فهمزة القطع تُنطق دائمًا في أول الكلام وفي وسطه، مثل: أحمد وسأل، وتُكتب أ أو إ.","ow":["","العبارة صحيحة، فهمزة القطع لا تختفي عند الوصل."]},
  {"q":"العبارة: همزة الوصل تُنطق عند وصلها بما قبلها.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فهمزة الوصل تُنطق إذا ابتدأنا بها الكلام، ولا تُنطق إذا وصلناها بما قبلها، مثل: هذا ابن أحمد.","ow":["همزة الوصل لا تُنطق عند الوصل، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: التاء المربوطة تُنطق هاءً عند الوقف.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالتاء المربوطة تُنطق هاءً عند الوقف، فنقول: قصة بالوقف قصه، ومدرسة بالوقف مدرسه.","ow":["","العبارة صحيحة، فالتاء المربوطة هاء في الوقف مثل غرفه."]},
  {"q":"العبارة: كلمة <b>بيتٌ</b> فيها تاء مربوطة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فبيتٌ تُنطق تاءً عند الوقف: بيت، فهي تاء مفتوحة وليست مربوطة، لأن التاء المربوطة تُنطق هاءً.","ow":["بيت تُنطق تاءً عند الوقف وليس هاءً، فهي تاء مفتوحة.",""]},
  {"q":"العبارة: همزة كلمة <b>استعانَ</b> همزة وصل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فاستعانَ تُكتب ألفًا دون همزة، ولا تُنطق همزتها عند الوصل، فهي همزة وصل.","ow":["","العبارة صحيحة، فهمزة استعان وصل وليست قطعًا."]},
];
window.BANK['a5']['a5-1-8'] = [
  {"q":"أقوى الحركات هي:","o":["الفتحة","الضمة","السكون","الكسرة"],"a":3,"why":"أقوى الحركات هي الكسرة، ثم الضمة، ثم الفتحة، ثم السكون وهو الأضعف. ونعتمد هذا الترتيب في رسم الهمزة المتوسطة.","ow":["الفتحة ثالثة في الترتيب وليست الأقوى.","الضمة ثانية في الترتيب وليست الأقوى.","السكون أضعف الحركات وليس الأقوى.",""]},
  {"q":"أضعف الحركات هي:","o":["السكون","الفتحة","الضمة","الكسرة"],"a":0,"why":"السكون أضعف الحركات، وهو آخر الترتيب: كسرة ثم ضمة ثم فتحة ثم سكون، وليس له حرف تُرسم عليه الهمزة.","ow":["","الفتحة أقوى من السكون.","الضمة أقوى من السكون.","الكسرة أقوى الحركات وليست الأضعف."]},
  {"q":"الحرف الذي يناسب الكسرة هو:","o":["الألف","الواو","الياء","الهاء"],"a":2,"why":"الكسرة يناسبها حرف الياء، فإذا كانت الكسرة أقوى الحركات رُسمت الهمزة على ياء، مثل: سُئل.","ow":["الألف تناسب الفتحة وليست الكسرة.","الواو تناسب الضمة وليست الكسرة.","","الهاء ليست من الحروف التي تُرسم عليها الهمزة."]},
  {"q":"الحرف الذي يناسب الضمة هو:","o":["الواو","الألف","الياء","الراء"],"a":0,"why":"الضمة يناسبها حرف الواو، فإذا كانت الضمة أقوى الحركات رُسمت الهمزة على واو، مثل: مؤمن.","ow":["","الألف تناسب الفتحة وليست الضمة.","الياء تناسب الكسرة وليست الضمة.","الراء ليست من الحروف التي تُرسم عليها الهمزة."]},
  {"q":"تُرسم الهمزة المتوسطة على ألف إذا كانت:","o":["الكسرة أقوى","الفتحة أقوى","الضمة أقوى","لا حركة لها"],"a":1,"why":"تُرسم الهمزة على ألف إذا كانت الفتحة أقوى الحركتين، لأن الألف هي الحرف المناسب للفتحة.","ow":["إذا كانت الكسرة أقوى رُسمت على ياء.","","إذا كانت الضمة أقوى رُسمت على واو.","للهمزة حركة أو سكون، ونقارن بينه وبين حركة ما قبلها."]},
  {"q":"حركة الهمزة في كلمة <b>سَأَلَ</b>:","o":["ضمة","كسرة","سكون","فتحة"],"a":3,"why":"في سَأَلَ الهمزة فيها فتحة، ولذلك نقول إنها مفتوحة، وما قبلها مفتوح أيضًا، فترسم على ألف.","ow":["ليست مضمومة، فلا ضمة فوقها.","ليست مكسورة، فلا كسرة تحتها.","ليست ساكنة، بل عليها فتحة.",""]},
  {"q":"سبب رسم الهمزة على ألف في <b>يأخذ</b>:","o":["الهمزة ساكنة وما قبلها مفتوح","الهمزة مكسورة","الهمزة مضمومة وما قبلها مضموم","ما قبلها ساكن"],"a":0,"why":"في يأخذ الهمزة ساكنة وما قبلها مفتوح، والفتحة أقوى من السكون، فتُرسم الهمزة على ألف.","ow":["","الهمزة ليست مكسورة، بل ساكنة.","الهمزة ليست مضمومة، والياء قبلها مفتوحة.","ما قبل الهمزة مفتوح وليس ساكنًا."]},
  {"q":"سبب رسم الهمزة على ألف في <b>هَيْأَة</b>:","o":["الهمزة مضمومة","الهمزة مفتوحة وما قبلها ساكن","الهمزة ساكنة وما قبلها مضموم","الهمزة مكسورة"],"a":1,"why":"في هَيْأَة الياء قبل الهمزة ساكنة والهمزة مفتوحة، والفتحة أقوى من السكون، فتُرسم الهمزة على ألف.","ow":["الهمزة ليست مضمومة، بل مفتوحة.","","الهمزة ليست ساكنة، بل مفتوحة.","الهمزة ليست مكسورة، بل مفتوحة."]},
  {"q":"أي الكلمات الآتية همزتها على ألف؟","o":["مؤمن","فؤاد","رأس","سُئل"],"a":2,"why":"رأس الهمزة فيها ساكنة وما قبلها مفتوح، فالفتحة أقوى، فتُرسم على ألف. أما مؤمن وفؤاد فعلى واو، وسُئل على ياء.","ow":["مؤمن فيها ضمة، فتُرسم الهمزة على واو.","فؤاد فيها ضمة، فتُرسم الهمزة على واو.","","سُئل فيها همزة مكسورة، فتُرسم على ياء."]},
  {"q":"أي الكلمات الآتية همزتها <b>ليست</b> على ألف؟","o":["سأل","رأس","يأخذ","مؤمن"],"a":3,"why":"مؤمن الهمزة فيها ساكنة وما قبلها مضموم، والضمة أقوى من السكون، فتُرسم على واو لا على ألف.","ow":["سأل همزتها على ألف لأن الفتحة أقوى.","رأس همزتها على ألف لأن الفتحة أقوى من السكون.","يأخذ همزتها على ألف لأن الفتحة أقوى من السكون.",""]},
  {"q":"الهمزة في كلمة <b>يرأف</b> تُرسم على:","o":["ألف","واو","ياء","سطر"],"a":0,"why":"الحرف الذي يناسب الكسرة هو الياء، فإذا كانت الكسرة أقوى الحركتين رُسمت الهمزة على ياء، مثل: سُئل.","ow":["","الواو تناسب الضمة، وهنا الحرف السابق مفتوح.","الياء تناسب الكسرة، وهنا الحرف السابق مفتوح.","الهمزة المتوسطة تُرسم على حرف، لا على السطر هنا."]},
  {"q":"في كلمة <b>المرأة</b> حركة ما قبل الهمزة:","o":["فتحة","ضمة","سكون","كسرة"],"a":2,"why":"في المرأة الراء ساكنة، والهمزة بعدها مفتوحة. والفتحة أقوى من السكون فتُرسم الهمزة على ألف.","ow":["ليس ما قبل الهمزة مفتوحًا، بل ساكنًا.","ليس ما قبل الهمزة مضمومًا.","","ليس ما قبل الهمزة مكسورًا."]},
  {"q":"الخطوة الثانية في رسم الهمزة المتوسطة هي:","o":["تحديد أقوى الحركتين","عدّ الحروف","كتابة الكلمة بخط النسخ","حذف الهمزة"],"a":0,"why":"بعد تحديد الحركتين نحدد أقواهما حسب الترتيب: كسرة ثم ضمة ثم فتحة ثم سكون، ثم نرسم الهمزة على الحرف المناسب.","ow":["","عدّ الحروف ليس من خطوات القاعدة.","نوع الخط ليس له علاقة بصورة الهمزة.","لا نحذف الهمزة، بل نرسمها على الحرف المناسب."]},
  {"q":"إذا كانت الهمزة مفتوحة وقبلها مفتوح، فإنها تُرسم على:","o":["واو","ياء","ألف","لا تُرسم"],"a":2,"why":"إذا كانت الهمزة مفتوحة وقبلها مفتوح فالفتحة هي الأقوى، والألف تناسب الفتحة، فتُرسم على ألف مثل: سَأَلَ.","ow":["الواو تناسب الضمة وليس الفتحة.","الياء تناسب الكسرة وليس الفتحة.","","الهمزة لا بد أن تُرسم على حرف في وسط الكلمة هنا."]},
  {"q":"إذا كانت الهمزة مفتوحة وقبلها ضمة، فإن الأقوى هي الضمة، لذلك الأنسب أن تُكتب على:","o":["ألف","ياء","سطر","واو"],"a":3,"why":"إذا كانت الهمزة مفتوحة وقبلها ضمة فالضمة أقوى من الفتحة، فتُرسم على واو مثل: فُؤاد.","ow":["الألف تناسب الفتحة، لكن الضمة أقوى.","الياء تناسب الكسرة، وليس عندنا كسرة.","لا تُترك الهمزة على السطر هنا، بل تُرسم على الواو.",""]},
  {"q":"العبارة: الفتحة أقوى من السكون.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فترتيب الحركات: كسرة ثم ضمة ثم فتحة ثم سكون، فالفتحة أقوى من السكون.","ow":["","العبارة صحيحة، فالسكون هو الأضعف."]},
  {"q":"العبارة: الكسرة أضعف الحركات.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالكسرة هي أقوى الحركات وليست أضعفها، والأضعف هو السكون، والكسرة تناسبها الياء.","ow":["الكسرة أقوى الحركات، فلا تكون أضعف.",""]},
  {"q":"العبارة: الهمزة في كلمة <b>سأل</b> مكتوبة على ألف.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فسأل الهمزة فيها مفتوحة وقبلها مفتوح، والفتحة تناسب الألف، فتُرسم على ألف.","ow":["","العبارة صحيحة، فالهمزة في سأل على ألف."]},
  {"q":"العبارة: الهمزة في كلمة <b>رأس</b> تُكتب على واو.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فرأس الهمزة فيها ساكنة وما قبلها مفتوح، والفتحة تناسب الألف، فتُكتب على ألف وليس على واو.","ow":["رأس ليس فيها ضمة تُرسم على واو، بل فتحة قبل الهمزة.",""]},
  {"q":"العبارة: الألف هو الحرف المناسب للفتحة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالألف تناسب الفتحة، والواو تناسب الضمة، والياء تناسب الكسرة، وبها نعرف صورة الهمزة.","ow":["","العبارة صحيحة، فالفتحة تناسبها الألف."]},
];
window.BANK['a5']['a5-1-9'] = [
  {"q":"تُرسم الهمزة المتوسطة على واو إذا كانت:","o":["الكسرة أقوى","الفتحة أقوى","الضمة أقوى","لا حركة"],"a":2,"why":"إذا كانت الضمة هي أقوى الحركتين رُسمت الهمزة المتوسطة على واو، لأن الواو هي الحرف المناسب للضمة.","ow":["الكسرة إذا كانت الأقوى رُسمت الهمزة على ياء.","الفتحة إذا كانت الأقوى رُسمت الهمزة على ألف.","","للهمزة حركة أو سكون، ولا نستغني عن النظر إلى حركتها وحركة ما قبلها."]},
  {"q":"أي الكلمات الآتية همزتها على واو؟","o":["رأس","مؤمن","سأل","يأخذ"],"a":1,"why":"مؤمن الهمزة فيها ساكنة وما قبلها مضموم، والضمة أقوى من السكون، فتُرسم على واو. أما رأس وسأل ويأخذ فعلى ألف.","ow":["رأس الفتحة قبل الهمزة، فتُرسم على ألف.","","سأل الفتحة أقوى، فتُرسم على ألف.","يأخذ الفتحة أقوى، فتُرسم على ألف."]},
  {"q":"سبب رسم الهمزة على واو في <b>مؤمن</b>:","o":["الهمزة ساكنة وما قبلها مضموم","الهمزة مفتوحة وقبلها مفتوح","الهمزة مكسورة","ما قبلها مفتوح"],"a":0,"why":"في مؤمن الهمزة ساكنة وما قبلها مضموم، والضمة أقوى من السكون، فتُرسم الهمزة على واو لأن الواو تناسب الضمة.","ow":["","الهمزة في مؤمن ساكنة، وما قبلها مضموم وليس مفتوحًا.","الهمزة في مؤمن ساكنة وليست مكسورة.","ما قبل الهمزة في مؤمن مضموم وليس مفتوحًا."]},
  {"q":"سبب رسم الهمزة على واو في <b>شُؤون</b>:","o":["الهمزة مفتوحة","الهمزة ساكنة","الهمزة مضمومة وما قبلها مضموم","ما قبلها مكسور"],"a":2,"why":"في شُؤون الهمزة مضمومة وما قبلها مضموم، فالحركتان متساويتان، والضمة تناسبها الواو، فتُرسم على واو.","ow":["الهمزة في شؤون مضمومة وليست مفتوحة.","الهمزة في شؤون مضمومة وليست ساكنة.","","ما قبل الهمزة في شؤون مضموم وليس مكسورًا."]},
  {"q":"سبب رسم الهمزة على واو في <b>يَؤُمُّ</b>:","o":["الهمزة مضمومة وما قبلها مفتوح","الهمزة مفتوحة وقبلها مفتوح","الهمزة مكسورة","الهمزة ساكنة وقبلها مفتوح"],"a":0,"why":"في يَؤُمُّ الهمزة مضمومة وما قبلها (الياء) مفتوح، والضمة أقوى من الفتحة، فتُرسم الهمزة على واو.","ow":["","الهمزة في يؤم مضمومة وليست مفتوحة.","الهمزة في يؤم مضمومة وليست مكسورة.","الهمزة في يؤم مضمومة وليست ساكنة."]},
  {"q":"سبب رسم الهمزة على واو في <b>ضَوْؤُها</b>:","o":["الهمزة مكسورة","الهمزة مضمومة وما قبلها ساكن","الهمزة مفتوحة وقبلها مفتوح","الهمزة ساكنة وقبلها مفتوح"],"a":1,"why":"في ضَوْؤُها الهمزة مضمومة وما قبلها (الواو) ساكن، والضمة أقوى من السكون، فتُرسم على واو.","ow":["الهمزة في ضوءها مضمومة وليست مكسورة.","","الهمزة في ضوءها مضمومة وليست مفتوحة، وما قبلها ساكن.","الهمزة في ضوءها مضمومة وليست ساكنة."]},
  {"q":"الهمزة في <b>فُؤاد</b> رُسمت على واو لأن:","o":["الهمزة ساكنة","الهمزة مكسورة","الهمزة مضمومة","الهمزة مفتوحة وقبلها مضموم"],"a":3,"why":"في فُؤاد الهمزة مفتوحة وما قبلها مضموم، والضمة أقوى من الفتحة، فتُرسم الهمزة على واو.","ow":["الهمزة في فؤاد مفتوحة وليست ساكنة.","الهمزة في فؤاد مفتوحة وليست مكسورة.","الهمزة في فؤاد مفتوحة وليست مضمومة، لكن ما قبلها مضموم.",""]},
  {"q":"الهمزة في كلمة <b>رُؤوس</b> تُرسم على واو لأن:","o":["حركتها فتحة","حركتها وحركة ما قبلها ضمة","ما قبلها ساكن","هي في أول الكلمة"],"a":1,"why":"في رُؤوس الهمزة مضمومة وما قبلها مضموم، فالحركتان ضمة وضمة متساويتان، والضمة تناسبها الواو، فتُرسم على واو.","ow":["الهمزة في رؤوس مضمومة وليست مفتوحة.","","ما قبل الهمزة في رؤوس مضموم وليس ساكنًا.","الهمزة في وسط الكلمة وليست في أولها."]},
  {"q":"حركة الهمزة في كلمة <b>مُؤدِّبة</b>:","o":["فتحة","ضمة","كسرة","سكون"],"a":0,"why":"مُؤدِّبة الهمزة فيها مفتوحة، وما قبلها (الميم) مضموم، والضمة أقوى من الفتحة، فتُرسم الهمزة على واو.","ow":["","الهمزة في مؤدبة ليست مضمومة، بل مفتوحة.","الهمزة في مؤدبة ليست مكسورة، بل مفتوحة.","الهمزة في مؤدبة ليست ساكنة، بل مفتوحة."]},
  {"q":"أي الكلمات الآتية تُكتب فيها الهمزة على واو؟","o":["مَسْؤولية","سأل","رأس","يأخذ"],"a":0,"why":"مَسْؤولية الهمزة فيها مضمومة وما قبلها ساكن، والضمة أقوى من السكون، فتُرسم على واو. أما سأل ورأس ويأخذ فعلى ألف.","ow":["","سأل الفتحة أقوى، فتُرسم الهمزة على ألف.","رأس الفتحة أقوى، فتُرسم الهمزة على ألف.","يأخذ الفتحة أقوى، فتُرسم الهمزة على ألف."]},
  {"q":"أي الكلمات الآتية تُكتب فيها الهمزة على ألف؟","o":["فؤاد","مؤمن","سأل","شؤون"],"a":2,"why":"سأل الهمزة مفتوحة وما قبلها مفتوح، والفتحة تناسب الألف، فتُرسم على ألف. أما فؤاد ومؤمن وشؤون ففيها ضمة أقوى.","ow":["فؤاد الضمة أقوى من الفتحة، فتُرسم على واو.","مؤمن الضمة أقوى من السكون، فتُرسم على واو.","","شؤون الضمة مع الضمة، فتُرسم على واو."]},
  {"q":"تكتب الهمزة على واو في كلمة:","o":["يُؤذي","يأتي","يرأف","المرأة"],"a":0,"why":"يؤذي الهمزة ساكنة وما قبلها مضموم، فالضمة أقوى فتُكتب على واو. أما يأتي ويرأف والمرأة ففيها الفتحة أقوى، فتُكتب على ألف.","ow":["","يأتي الهمزة ساكنة وما قبلها مفتوح، فتُكتب على ألف.","يرأف الهمزة ساكنة وما قبلها مفتوح، فتُكتب على ألف.","المرأة الراء ساكنة والهمزة مفتوحة، فالفتحة أقوى وتُكتب على ألف."]},
  {"q":"الحركة التي تأتي بعد الكسرة في القوة هي:","o":["الفتحة","الضمة","السكون","التنوين"],"a":1,"why":"ترتيب قوة الحركات: الكسرة ثم الضمة ثم الفتحة ثم السكون، فالتي تأتي بعد الكسرة هي الضمة.","ow":["الفتحة بعد الضمة، وليست بعد الكسرة مباشرة.","","السكون هو الأضعف وهو آخر الترتيب.","التنوين ليس من الحركات التي نقارن بينها لرسم الهمزة."]},
  {"q":"إذا اجتمعت ضمة وفتحة على الهمزة وما قبلها، فالأقوى:","o":["الفتحة","السكون","لا شيء","الضمة"],"a":3,"why":"الضمة أقوى من الفتحة في الترتيب: كسرة ثم ضمة ثم فتحة ثم سكون، فتُرسم الهمزة على الواو التي تناسب الضمة.","ow":["الفتحة أضعف من الضمة، فلا تكون الأقوى.","السكون أضعف الحركات، فلا يكون الأقوى.","الحركات لها ترتيب في القوة، ولذلك نختار الأقوى منها.",""]},
  {"q":"تُرسم الهمزة على واو إذا كانت ساكنة وقبلها:","o":["مضموم","مفتوح","مكسور","ساكن"],"a":0,"why":"إذا كانت الهمزة ساكنة وقبلها مضموم فالضمة أقوى من السكون، فتُرسم الهمزة على واو، مثل: المُؤْمِن.","ow":["","إذا كان ما قبل الهمزة الساكنة مفتوحًا رُسمت على ألف، مثل رأس.","إذا كان ما قبل الهمزة الساكنة مكسورًا رُسمت على ياء، مثل بِئر.","إذا كان ما قبلها ساكنًا فهذه حالة أخرى، وليست مما درسناه هنا."]},
  {"q":"العبارة: الضمة أقوى من الفتحة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فترتيب الحركات: كسرة ثم ضمة ثم فتحة ثم سكون، فالضمة أقوى من الفتحة.","ow":["","العبارة صحيحة، فالضمة تأتي قبل الفتحة في القوة."]},
  {"q":"العبارة: الهمزة في <b>فؤاد</b> تُكتب على ألف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، ففؤاد الهمزة فيها مفتوحة وما قبلها مضموم، والضمة أقوى من الفتحة، فتُكتب على واو وليس على ألف.","ow":["الهمزة في فؤاد على واو لأن الضمة أقوى، وليست على ألف.",""]},
  {"q":"العبارة: الهمزة في <b>مسؤولية</b> تُكتب على واو.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمسؤولية الهمزة فيها مضمومة وما قبلها ساكن، والضمة أقوى من السكون، فتُكتب على واو.","ow":["","العبارة صحيحة، فالهمزة في مسؤولية على واو."]},
  {"q":"العبارة: الواو هو الحرف المناسب للكسرة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالواو تناسب الضمة، أما الكسرة فتناسبها الياء، والفتحة تناسبها الألف.","ow":["الواو للضمة وليست للكسرة، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: ضمة مع ضمة، فالحركتان متساويتان وتُكتب الهمزة على واو.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فإذا كانت الحركتان ضمة وضمة فهما متساويتان، والضمة تناسبها الواو، فتُكتب الهمزة على واو، مثل: شُؤون.","ow":["","العبارة صحيحة، فالضمة مع الضمة تُكتب الهمزة على واو."]},
];
window.BANK['a5']['a5-1-10'] = [
  {"q":"علامة الرفع الأصلية هي:","o":["الفتحة","الضمة","الكسرة","السكون"],"a":1,"why":"علامة الرفع الأصلية هي الضمة، مثل: الصدقُ منجاةٌ. وما سواها من الواو والألف فعلامات فرعية.","ow":["الفتحة علامة نصب وليست علامة رفع.","","الكسرة علامة جر وليست علامة رفع.","السكون ليس علامة الرفع الأصلية، فالرفع بالضمة."]},
  {"q":"علامة رفع المبتدأ والخبر المفردين:","o":["الألف","الواو","الياء","الضمة"],"a":3,"why":"المبتدأ والخبر المفردان يُرفعان بالضمة وهي علامة الرفع الأصلية، مثل: كتابُ الله نورٌ. فالضمة على آخر الكلمتين.","ow":["الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم والأسماء الخمسة.","الياء ليست علامة رفع، بل علامة جر ونصب.",""]},
  {"q":"علامة رفع المبتدأ في: <b>كتابُ اللهِ نورٌ</b>","o":["الضمة","الألف","الواو","الفتحة"],"a":0,"why":"كتابُ اسم مفرد، والمفرد يُرفع بالضمة وهي العلامة الأصلية للرفع. فعلامة رفع المبتدأ هنا هي الضمة وليست الألف ولا الواو.","ow":["","الألف علامة رفع المثنى، وكتاب مفرد.","الواو علامة رفع جمع المذكر السالم، وكتاب مفرد.","الفتحة علامة نصب وليست علامة رفع."]},
  {"q":"علامة رفع المبتدأ في: <b>الأعمالُ موجبةٌ للثواب</b>","o":["الألف","الواو","الضمة","الياء"],"a":2,"why":"الأعمال جمع تكسير لأن صورة المفرد عمل تغيرت. وجمع التكسير يُرفع بالضمة، فنقول: الأعمالُ موجبةٌ للثواب.","ow":["الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم.","","الياء ليست علامة رفع هنا."]},
  {"q":"علامة رفع الخبر في: <b>الوالدانِ حنونانِ</b>","o":["الألف","الضمة","الواو","الياء"],"a":0,"why":"حنونان مثنى لأنه يدل على اثنين، وفي آخره ألف ونون. والمثنى يُرفع بالألف، فعلامة رفع الخبر الألف.","ow":["","الضمة علامة رفع المفرد، وحنونان مثنى.","الواو علامة رفع جمع المذكر السالم.","الياء ليست علامة رفع هنا."]},
  {"q":"علامة رفع المبتدأ في: <b>المسلمونَ إخوةٌ</b>","o":["الألف","الضمة","الفتحة","الواو"],"a":3,"why":"المسلمون جمع مذكر سالم، فيُرفع بالواو، فنقول: المسلمون إخوة. وإخوة خبر مرفوع بالضمة.","ow":["الألف علامة رفع المثنى.","الضمة علامة رفع المفرد وجمع التكسير، والمسلمون جمع مذكر سالم.","الفتحة علامة نصب.",""]},
  {"q":"علامة رفع الخبر في: <b>الطالباتُ مجتهداتٌ</b>","o":["الضمة","الألف","الواو","الياء"],"a":0,"why":"مجتهدات جمع مؤنث سالم، وجمع المؤنث السالم يُرفع بالضمة، فنقول: الطالباتُ مجتهداتٌ.","ow":["","الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم.","الياء ليست علامة رفع هنا."]},
  {"q":"علامة رفع المبتدأ في: <b>أخوك مجتهدٌ</b>","o":["الضمة","الألف","الواو","الكسرة"],"a":2,"why":"أخوك من الأسماء الخمسة، وهي تُرفع بالواو، فنقول: أخوك مجتهد. فعلامة رفع المبتدأ الواو.","ow":["الضمة علامة رفع المفرد، وأخوك له علامة خاصة.","الألف علامة رفع المثنى.","","الكسرة علامة جر وليست علامة رفع."]},
  {"q":"أي الكلمات الآتية من الأسماء الخمسة؟","o":["ابنُك","أبوك","جدّك","عمُّك"],"a":1,"why":"أبوك من الأسماء الخمسة: أبوك وأخوك وحموك وذو وفوك. أما ابنُك وجدّك وعمُّك فليست منها.","ow":["ابنك ليس من الأسماء الخمسة، فيُرفع بالضمة.","","جدّك ليس من الأسماء الخمسة، فيُرفع بالضمة.","عمُّك ليس من الأسماء الخمسة، فيُرفع بالضمة."]},
  {"q":"علامة رفع الأسماء الخمسة:","o":["الضمة","الألف","الياء","الواو"],"a":3,"why":"الأسماء الخمسة تُرفع بالواو، مثل: أبوك صادق، وأخوك مجتهد. وهذه علامة فرعية للرفع.","ow":["الضمة هي الأصل لغير الأسماء الخمسة.","الألف علامة رفع المثنى.","الياء ليست علامة رفع، بل علامة نصب وجر.",""]},
  {"q":"تُرفع بالألف:","o":["المفرد","المثنى","جمع التكسير","جمع المذكر السالم"],"a":1,"why":"المثنى يُرفع بالألف، مثل: الطالبان مجتهدان، فالألف والنون في آخره علامة الرفع. أما المفرد وجمع التكسير فيُرفعان بالضمة.","ow":["المفرد يُرفع بالضمة.","","جمع التكسير يُرفع بالضمة.","جمع المذكر السالم يُرفع بالواو."]},
  {"q":"تُرفع بالواو:","o":["المثنى","المفرد","جمع المذكر السالم","جمع المؤنث السالم"],"a":2,"why":"جمع المذكر السالم يُرفع بالواو مثل: المسلمون. أما المفرد وجمع المؤنث السالم فيُرفعان بالضمة، والمثنى بالألف.","ow":["المثنى يُرفع بالألف.","المفرد يُرفع بالضمة.","","جمع المؤنث السالم يُرفع بالضمة."]},
  {"q":"علامة رفع الخبر في: <b>الطالبانِ مجتهدانِ</b>","o":["الألف","الواو","الضمة","الياء"],"a":0,"why":"مجتهدان مثنى، والمثنى يُرفع بالألف، فنقول: الطالبان مجتهدان، وعلامة رفع الخبر الألف.","ow":["","الواو علامة رفع جمع المذكر السالم.","الضمة علامة رفع المفرد.","الياء ليست علامة رفع هنا."]},
  {"q":"علامة رفع المبتدأ في: <b>العلماءُ ورثةُ الأنبياء</b>","o":["الألف","الضمة","الواو","الياء"],"a":1,"why":"العلماء جمع تكسير، لأن صورة المفرد عالم تغيرت. وجمع التكسير يُرفع بالضمة، فنقول: العلماءُ ورثةُ الأنبياء.","ow":["الألف علامة رفع المثنى.","","الواو علامة رفع جمع المذكر السالم.","الياء ليست علامة رفع هنا."]},
  {"q":"يُرفع جمع المؤنث السالم بـ:","o":["الواو","الألف","الضمة","الياء"],"a":2,"why":"جمع المؤنث السالم يُرفع بالضمة، مثل: الدرجاتُ الرفيعةُ غايةُ المؤمن. فلا نرفعه بالواو ولا بالألف.","ow":["الواو علامة رفع جمع المذكر السالم.","الألف علامة رفع المثنى.","","الياء ليست علامة رفع هنا."]},
  {"q":"العبارة: المبتدأ والخبر مرفوعان دائمًا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمبتدأ والخبر مرفوعان دائمًا، لكن علامة الرفع تختلف: ضمة أو ألف أو واو.","ow":["","العبارة صحيحة، فالرفع هو حكم المبتدأ والخبر."]},
  {"q":"العبارة: يُرفع المثنى بالواو.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمثنى يُرفع بالألف مثل: الوالدان، أما الواو فلجمع المذكر السالم والأسماء الخمسة.","ow":["المثنى يُرفع بالألف وليس بالواو.",""]},
  {"q":"العبارة: <b>أخوك</b> من الأسماء الخمسة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأبوك من الأسماء الخمسة: أبوك وأخوك وحموك وذو وفوك، وهي تُرفع بالواو، فنقول: أخوك مجتهد.","ow":["","العبارة صحيحة، فأخوك من الأسماء الخمسة."]},
  {"q":"العبارة: يُرفع جمع التكسير بالألف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فجمع التكسير يُرفع بالضمة مثل: الأعمالُ موجبةٌ للأجر، أما الألف فهي علامة رفع المثنى.","ow":["جمع التكسير يُرفع بالضمة وليس بالألف.",""]},
  {"q":"العبارة: يُرفع جمع المذكر السالم بالواو.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فجمع المذكر السالم يُرفع بالواو، مثل: المؤمنون مخلصون، فالواو والنون في آخره هما علامة الرفع.","ow":["","العبارة صحيحة، فالواو علامة رفعه."]},
];
window.BANK['a5']['a5-1-11'] = [
  {"q":"الفاعل في جملة: <b>تتعاونُ الصديقتانِ على الخير</b>","o":["تتعاونُ","الخير","الصديقتانِ","على"],"a":2,"why":"الفاعل هو من قام بالفعل. في جملة تتعاون الصديقتان على الخير، الصديقتان هما اللتان تتعاونان، فهما الفاعل.","ow":["تتعاونُ هو الفعل نفسه، وليس من قام به.","الخير هو ما يتعاونان عليه وهو اسم مجرور بعد على.","","على حرف جر، وليس فاعلًا."]},
  {"q":"علامة رفع الفاعل <b>التلوثُ</b> في: يسبّبُ التلوثُ الأمراض","o":["الضمة","الألف","الواو","الياء"],"a":0,"why":"التلوث اسم مفرد، والمفرد يُرفع بالضمة وهي العلامة الأصلية للرفع، فنقول: يسبب التلوثُ الأمراض.","ow":["","الألف علامة رفع المثنى، والتلوث مفرد.","الواو علامة رفع جمع المذكر السالم والأسماء الخمسة.","الياء ليست علامة رفع."]},
  {"q":"علامة رفع الفاعل <b>الضوضاءُ</b> في: تكثرُ الضوضاءُ في المدن","o":["الألف","الواو","الضمة","الياء"],"a":2,"why":"الضوضاء اسم مفرد، والمفرد يُرفع بالضمة وهي العلامة الأصلية، فنقول: تكثر الضوضاءُ في المدن.","ow":["الألف علامة رفع المثنى، والضوضاء مفرد.","الواو علامة رفع جمع المذكر السالم.","","الياء ليست علامة رفع."]},
  {"q":"علامة رفع الفاعل <b>الزائرونَ</b> في: يستمتعُ الزائرونَ بالحديقة","o":["الواو","الألف","الضمة","الياء"],"a":0,"why":"الزائرون جمع مذكر سالم لأنه زائر + ون، وجمع المذكر السالم يُرفع بالواو، فنقول: يستمتع الزائرونَ بالحديقة.","ow":["","الألف علامة رفع المثنى، والزائرون جمع.","الضمة علامة رفع المفرد وجمع التكسير، والزائرون جمع مذكر سالم.","الياء علامة نصب وجر لجمع المذكر السالم."]},
  {"q":"علامة رفع الفاعل <b>الطالبانِ</b> في: يذاكرُ الطالبانِ الدرسَ","o":["الضمة","الألف","الواو","الفتحة"],"a":1,"why":"الطالبان مثنى لأنه يدل على اثنين وفي آخره ألف ونون، والمثنى يُرفع بالألف، فنقول: يذاكر الطالبانِ الدرس.","ow":["الضمة علامة رفع المفرد، والطالبان مثنى.","","الواو علامة رفع جمع المذكر السالم.","الفتحة علامة نصب وليست علامة رفع."]},
  {"q":"علامة رفع الفاعل <b>أبوك</b> في: يُنفقُ أبوك ماله باعتدال","o":["الضمة","الألف","الياء","الواو"],"a":3,"why":"أبوك من الأسماء الخمسة التي تُرفع بالواو، فنقول: ينفق أبوك ماله باعتدال. والأسماء الخمسة: أبوك وأخوك وحموك وذو وفوك.","ow":["الضمة علامة رفع المفرد، لكن أبوك من الأسماء الخمسة.","الألف علامة رفع المثنى، وأبوك ليس مثنى.","الياء ليست علامة رفع.",""]},
  {"q":"علامة رفع <b>الخضراواتُ</b> الفاعل في: تمدُّ الخضراواتُ الجسمَ بالفيتامينات","o":["الضمة","الألف","الواو","الياء"],"a":0,"why":"الخضراوات جمع مؤنث سالم لأنها تنتهي بألف وتاء، وجمع المؤنث السالم يُرفع بالضمة، فعلامة رفع الفاعل الضمة.","ow":["","الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم.","الياء ليست علامة رفع."]},
  {"q":"علامة رفع الفاعل <b>الجراثيمُ</b> في: تعيشُ الجراثيمُ في الأماكن القذرة","o":["الألف","الواو","الضمة","الياء"],"a":2,"why":"الجراثيم جمع تكسير لأن صورة المفرد جرثومة تغيرت. وجمع التكسير يُرفع بالضمة، فعلامة رفع الفاعل الضمة.","ow":["الألف علامة رفع المثنى.","الواو علامة رفع جمع المذكر السالم.","","الياء ليست علامة رفع."]},
  {"q":"علامة رفع الفاعل <b>المصابونَ</b>:","o":["الواو","الألف","الضمة","الياء"],"a":0,"why":"المصابون جمع مذكر سالم لأنه مصاب + ون، وجمع المذكر السالم يُرفع بالواو في الفاعل وفي المبتدأ.","ow":["","الألف علامة رفع المثنى، والمصابون جمع.","الضمة علامة رفع المفرد وجمع التكسير، والمصابون جمع مذكر سالم.","الياء علامة نصب وجر لجمع المذكر السالم، وليست علامة رفع."]},
  {"q":"الفاعل يكون دائمًا:","o":["منصوبًا","مجرورًا","مرفوعًا","مجزومًا"],"a":2,"why":"الفاعل هو من قام بالفعل، وهو مرفوع دائمًا، وعلامة رفعه الأصلية الضمة، وقد تكون الألف أو الواو بحسب نوعه.","ow":["الفاعل لا يكون منصوبًا، فالمنصوب مثل المفعول به.","الفاعل لا يكون مجرورًا، فالمجرور يأتي بعد حرف الجر.","","الجزم يكون في الأفعال، والفاعل اسم مرفوع."]},
  {"q":"تُرفع بالألف:","o":["الأسماء الخمسة","الفاعل المثنى","جمع التكسير","المفرد"],"a":1,"why":"المثنى يُرفع بالألف، مثل: يذاكر الطالبان الدرس. أما الأسماء الخمسة فتُرفع بالواو، وجمع التكسير والمفرد بالضمة.","ow":["الأسماء الخمسة تُرفع بالواو وليس بالألف.","","جمع التكسير يُرفع بالضمة وليس بالألف.","المفرد يُرفع بالضمة وليس بالألف."]},
  {"q":"علامة رفع الفاعل في: <b>يقرأُ الولدُ القصةَ</b>","o":["الواو","الألف","الياء","الضمة"],"a":3,"why":"الولد اسم مفرد، والمفرد يُرفع بالضمة وهي علامة الرفع الأصلية، فنقول: يقرأ الولدُ القصة.","ow":["الواو علامة رفع جمع المذكر السالم والأسماء الخمسة.","الألف علامة رفع المثنى، والولد مفرد.","الياء ليست علامة رفع.",""]},
  {"q":"علامة رفع الفاعل <b>الكليتانِ</b>:","o":["الألف","الضمة","الواو","الفتحة"],"a":0,"why":"الكليتان مثنى لأنه يدل على كليتين وفي آخره ألف ونون، والمثنى يُرفع بالألف، فعلامة رفع الفاعل الألف.","ow":["","الضمة علامة رفع المفرد، والكليتان مثنى.","الواو علامة رفع جمع المذكر السالم.","الفتحة علامة نصب وليست علامة رفع."]},
  {"q":"الفاعل هو الاسم الذي يدل على:","o":["من وقع عليه الفعل","مكان الفعل","من فعل الفعل","زمن الفعل"],"a":2,"why":"الفاعل هو الاسم الذي دلّ على من قام بالفعل، مثل: يقرأ الولدُ، فالولد هو الذي يقرأ.","ow":["من وقع عليه الفعل هو المفعول به وليس الفاعل.","مكان الفعل لا يسمى فاعلًا، بل ظرف مكان.","","زمن الفعل لا يسمى فاعلًا، بل ظرف زمان."]},
  {"q":"علامة رفع الفاعل <b>أخوك</b>:","o":["الواو","الضمة","الألف","الياء"],"a":0,"why":"أخوك من الأسماء الخمسة، وتُرفع بالواو، فنقول: يعلّم أخوك فوائد الادخار، فعلامة رفع الفاعل هي الواو.","ow":["","الضمة علامة رفع المفرد، لكن أخوك له علامة خاصة هي الواو.","الألف علامة رفع المثنى، وأخوك ليس مثنى.","الياء ليست علامة رفع."]},
  {"q":"العبارة: الفاعل يكون مرفوعًا دائمًا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالفاعل مرفوع دائمًا، وعلامة رفعه الأصلية الضمة، وقد تكون الألف أو الواو.","ow":["","العبارة صحيحة، فالرفع هو حكم الفاعل دائمًا."]},
  {"q":"العبارة: يُرفع الفاعل المثنى بالواو.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمثنى يُرفع بالألف مثل: يذاكر الطالبانِ الدرس. أما الواو فلجمع المذكر السالم والأسماء الخمسة.","ow":["المثنى يُرفع بالألف وليس بالواو، فلا تصح العبارة.",""]},
  {"q":"العبارة: <b>أبوك</b> فاعل مرفوع بالواو في جملة: يُنفقُ أبوك ماله.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأبوك من الأسماء الخمسة، وتُرفع بالواو، فهو فاعل مرفوع وعلامة رفعه الواو في جملة: ينفق أبوك ماله.","ow":["","العبارة صحيحة، فأبوك فاعل مرفوع بالواو."]},
  {"q":"العبارة: يُرفع جمع المؤنث السالم بالألف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فجمع المؤنث السالم يُرفع بالضمة مثل: الخضراواتُ، أما الألف فعلامة رفع المثنى.","ow":["جمع المؤنث السالم يُرفع بالضمة وليس بالألف.",""]},
  {"q":"العبارة: الجملة الفعلية تبدأ بفعل ثم الفاعل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالجملة الفعلية تبدأ بفعل، ثم يأتي الفاعل الذي قام بالفعل، مثل: يقرأ الولدُ.","ow":["","العبارة صحيحة، فركنا الجملة الفعلية هما الفعل والفاعل."]},
];
window.BANK['a5']['a5-1-12'] = [
  {"q":"النداء هو طلب:","o":["الإجابة عن سؤال","الإقبال من المخاطَب أو تنبيهه","نفي الفعل","المقارنة بين شيئين"],"a":1,"why":"النداء هو طلب الإقبال من المخاطَب أو تنبيهه، مثل: يا أحمد، فأنت تطلب منه أن يقبل عليك وينتبه.","ow":["الإجابة عن سؤال تكون بجملة خبرية وليست نداء.","","نفي الفعل يكون بأدوات النفي مثل لم ولا.","المقارنة بين شيئين هي اسم التفضيل."]},
  {"q":"من حروف النداء:","o":["هل","لم","يا","في"],"a":2,"why":"يا من حروف النداء، فنقول: يا أحمد، ويا بنتي. أما هل فللاستفهام، ولم للنفي، وفي حرف جر.","ow":["هل حرف استفهام نسأل به، وليس للنداء.","لم حرف نفي وجزم، وليس للنداء.","","في حرف جر، وليس للنداء."]},
  {"q":"أي الجمل الآتية فيها أسلوب نداء؟","o":["يا أحمدُ اجتهدْ","هل ذاكرتَ دروسك؟","لم يحضر الطالبُ","ذهب عليٌّ إلى المسجد"],"a":0,"why":"يا أحمدُ اجتهدْ فيها حرف النداء يا، وهو يطلب إقبال أحمد وانتباهه، فهي جملة نداء.","ow":["","هل ذاكرت دروسك جملة استفهام، لأن فيها هل.","لم يحضر الطالب جملة منفية، لأن فيها لم.","ذهب علي إلى المسجد جملة خبرية، وليس فيها حرف نداء."]},
  {"q":"الأسلوب الصحيح في النداء هو أن نقول:","o":["يا الطلابُ","يا الناسُ","يا أيها الناسُ","يا الولدُ"],"a":2,"why":"عندما يكون المنادى أوله ال لا نقول يا الناس، بل نقول: يا أيها الناس، فنستخدم أيّ بعد حرف النداء.","ow":["يا الطلاب خطأ، لأن حرف النداء لا يدخل على ما أوله ال مباشرة.","يا الناس خطأ، لأن حرف النداء لا يدخل على ما أوله ال مباشرة.","","يا الولد خطأ، لأن حرف النداء لا يدخل على ما أوله ال مباشرة."]},
  {"q":"نُكمل بالمناسب: <b>يا ... الطلابُ اجتهدوا</b>","o":["أيتها","أيها","أيّ","يا"],"a":1,"why":"الطلاب مذكر، ونناديه بقولنا: يا أيها الطلاب، لأن أيها للمذكر، والفعل بعده للمذكرين اجتهدوا.","ow":["أيتها للمؤنث مثل: يا أيتها الطالبات، والطلاب مذكر.","","أي وحدها لا تكفي هنا، فالصيغة الصحيحة يا أيها.","يا حرف النداء ولا تُكرّر هنا."]},
  {"q":"نُكمل بالمناسب: <b>يا ... المعلمةُ</b>","o":["أيها","أيتها","هل","لم"],"a":1,"why":"المعلمة مؤنث، فنناديها بقولنا: يا أيتها المعلمة، لأن أيتها للمؤنث، كما أن أيها للمذكر.","ow":["أيها للمذكر مثل: يا أيها الطلاب، والمعلمة مؤنث.","","هل أداة استفهام، وليست للنداء.","لم أداة نفي، وليست للنداء."]},
  {"q":"اسم التفضيل في جملة: <b>المسجدُ أقربُ من المدرسة</b>","o":["المسجدُ","المدرسة","أقربُ","من"],"a":2,"why":"أقرب اسم تفضيل، يدل على أن المسجد والمدرسة اشتركا في صفة القرب، وزاد المسجد فيها. ويأتي بعده من.","ow":["المسجد اسم مقارَن وهو المبتدأ، وليس اسم التفضيل.","المدرسة اسم مقارَن به، وليست اسم التفضيل.","","من حرف جر يأتي بعد اسم التفضيل، وليس هو اسم التفضيل."]},
  {"q":"أي الكلمات الآتية يُعدّ اسم تفضيل؟","o":["فاضل","أفضل","مفضّل","فضل"],"a":1,"why":"أفضل على وزن أفعل، وتدل على زيادة في صفة الفضل، فهي اسم تفضيل. أما فاضل فاسم فاعل، ومفضّل اسم مفعول، وفضل مصدر.","ow":["فاضل اسم فاعل من فضل، وليس اسم تفضيل.","","مفضّل اسم مفعول، وليس اسم تفضيل.","فضل مصدر أو اسم، وليس على وزن أفعل."]},
  {"q":"اسم التفضيل من كلمة <b>كبير</b>:","o":["كابر","مكبَّر","أكبر","كبيرة"],"a":2,"why":"اسم التفضيل من كبير هو أكبر، على وزن أفعل، ويدل على زيادة في الكبر، فنقول: الجمل أكبر من الحصان.","ow":["كابر ليست اسم تفضيل.","مكبّر اسم مفعول، وليس اسم تفضيل.","","كبيرة مؤنث كبير، وليست اسم تفضيل."]},
  {"q":"اسم التفضيل من كلمة <b>جميل</b>:","o":["أجمل","جميلة","مجمَّل","جمال"],"a":0,"why":"اسم التفضيل من جميل هو أجمل، على وزن أفعل، ويدل على زيادة في الجمال، فنقول: الورد أجمل من الشوك.","ow":["","جميلة هي مؤنث جميل، وليست اسم تفضيل.","مجمّل اسم مفعول، وليس اسم تفضيل.","جمال مصدر، وليس اسم تفضيل."]},
  {"q":"يأتي بعد اسم التفضيل غالبًا حرف:","o":["(هل)","(لم)","(يا)","(من)"],"a":3,"why":"يأتي بعد اسم التفضيل غالبًا حرف الجر من لتبيين المقارَن به، مثل: علي أطول من سعيد.","ow":["هل أداة استفهام ولا تأتي بعد اسم التفضيل.","لم أداة نفي وجزم ولا تأتي بعد اسم التفضيل.","يا حرف نداء ولا يأتي بعد اسم التفضيل.",""]},
  {"q":"اسم التفضيل يدل على أن:","o":["شيئين اشتركا في صفة وزاد أحدهما فيها","شيئًا واحدًا فقط له صفة","الشيء لا صفة له","الفعل انتهى"],"a":0,"why":"اسم التفضيل يدل على أن شيئين اشتركا في صفة، وزاد أحدهما فيها على الآخر، مثل: علي أطول من سعيد.","ow":["","التفضيل يحتاج إلى شيئين، وليس شيئًا واحدًا فقط.","اسم التفضيل يدل على صفة موجودة، فلا يكون الشيء بلا صفة.","انتهاء الفعل يدل عليه الفعل الماضي، وليس اسم التفضيل."]},
  {"q":"في جملة <b>عليٌّ أطولُ من سعيد</b> الذي زاد في الطول هو:","o":["عليٌّ","سعيد","كلاهما بالتساوي","لا أحد"],"a":0,"why":"في علي أطول من سعيد اشترك الاثنان في الطول، لكن عليًّا زاد على سعيد، فالأطول هو علي.","ow":["","سعيد هو المقارَن به، وهو أقل في الطول.","لو كانا متساويين لما قلنا أطول، فاسم التفضيل يدل على الزيادة.","اسم التفضيل يدل على أن أحدهما زاد."]},
  {"q":"الكلمة <b>قريب</b> ليست اسم تفضيل لأنها:","o":["فعل","صفة عادية ليس فيها تفضيل","حرف","منادى"],"a":1,"why":"قريب صفة عادية تدل على القرب فقط، وليس فيها زيادة على شيء آخر. أما أقرب فهي اسم التفضيل لأنها على وزن أفعل.","ow":["قريب ليست فعلًا، فهي صفة.","","قريب ليست حرفًا، فهي صفة.","قريب ليست منادى، والمنادى هو من نناديه بيا."]},
  {"q":"يا أيتها الطالباتُ، الكلمة التي يُنادى بها المؤنث:","o":["أيها","أيتها","أيّ فقط","هل"],"a":1,"why":"المنادى المؤنث الذي أوله ال نقول له: يا أيتها، مثل: يا أيتها الطالبات. أما المذكر فيا أيها.","ow":["أيها للمذكر مثل: يا أيها الطلاب.","","أي وحدها لا تكفي، فنقول أيتها للمؤنث.","هل ليست من ألفاظ النداء، فهي للاستفهام."]},
  {"q":"العبارة: <b>يا</b> من حروف النداء.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فيا أشهر حروف النداء، فنقول: يا أحمد ويا بنتي ويا أيها الناس، وهي تطلب الإقبال والانتباه.","ow":["","العبارة صحيحة، فحرف النداء الأشهر هو يا."]},
  {"q":"العبارة: نقول: يا الطلابُ.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فلا نقول يا الطلاب لأن المنادى أوله ال، بل نقول: يا أيها الطلاب، فنستخدم أيّ بعد حرف النداء.","ow":["لا نجمع حرف النداء يا مع ال مباشرة، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: <b>أجمل</b> اسم تفضيل.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأجمل على وزن أفعل، وتدل على الزيادة في الجمال، مثل: الورد أجمل من الشوك.","ow":["","العبارة صحيحة، فأجمل اسم تفضيل."]},
  {"q":"العبارة: اسم التفضيل يأتي غالبًا بعده حرف (هل).","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فاسم التفضيل يأتي بعده غالبًا حرف الجر من، مثل: علي أطول من سعيد، وليس هل.","ow":["هل أداة استفهام ولا تأتي بعد اسم التفضيل.",""]},
  {"q":"العبارة: للمنادى المؤنث نقول يا أيتها.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمنادى المؤنث نقول له يا أيتها، مثل: يا أيتها الطالبات، والمذكر يا أيها.","ow":["","العبارة صحيحة، فأيتها للمؤنث."]},
];
window.BANK['a5']['a5-1-13'] = [
  {"q":"الخط الذي ندرسه في كتاب لغتي هو:","o":["خط الرقعة","خط الثلث","خط النسخ","الخط الكوفي"],"a":2,"why":"الخط الذي ندرسه في كتاب لغتي هو خط النسخ، وهو الذي كُتبت به الآيات القرآنية في الكتاب.","ow":["خط الرقعة خط سريع للكتابة اليومية، وليس الذي ندرسه.","خط الثلث خط للزخرفة، وليس الذي ندرسه.","","الخط الكوفي خط قديم، وليس الذي ندرسه في الكتاب."]},
  {"q":"سُمّي خط النسخ بهذا الاسم لأنه استُخدم في:","o":["نسخ الكتب والمصاحف","الرسم","لوحات الشوارع","كتابة الأرقام فقط"],"a":0,"why":"سُمّي خط النسخ بهذا الاسم لأنه كان يُستخدم في نسخ الكتب والمصاحف، أي في كتابتها وتدوينها.","ow":["","ليس اسمه من الرسم، بل من نسخ الكتب.","ليس اسمه من لوحات الشوارع، بل من نسخ الكتب.","ليس اسمه من كتابة الأرقام، بل من نسخ الكتب والمصاحف."]},
  {"q":"من مزايا خط النسخ الجمالية:","o":["إهمال الحركات","صعوبة قراءته","روعة حروفه وجمال تركيبه","اختلاف أحجام الحروف"],"a":2,"why":"من مميزات خط النسخ روعة حروفه وجمال تركيبه، أي أن شكل حروفه جميل ومتناسق، وهذا يجعل القراءة به ممتعة.","ow":["إهمال الحركات ليس ميزة، فمن مميزاته الاهتمام بوضع الحركات.","صعوبة القراءة ليست ميزة، فخط النسخ سهل القراءة.","","اختلاف الأحجام ليس من مميزاته، فأحجام حروفه متساوية."]},
  {"q":"من مزايا خط النسخ في الكتابة:","o":["الاهتمام بوضع الحركات","إغلاق كل الحروف","ضعف وضوح الحروف","كتابة الحروف متداخلة"],"a":0,"why":"من مميزات خط النسخ الاهتمام بوضع الحركات في أماكنها الصحيحة، فتُقرأ الكلمات قراءة صحيحة.","ow":["","حروف النسخ واضحة ومفتوحة، وليست مغلقة كلها.","وضوح الحروف من مميزات خط النسخ، وليس ضعف الوضوح.","الحروف في خط النسخ غير متداخلة، بل واضحة."]},
  {"q":"الحروف في خط النسخ من حيث الحجم:","o":["مختلفة جدًا","متساوية","صغيرة فقط","كبيرة فقط"],"a":1,"why":"من مميزات خط النسخ تساوي أحجام الحروف، فتكون الحروف متناسقة وجميلة وسهلة القراءة.","ow":["الحروف ليست مختلفة جدًا، بل متساوية.","","الحروف ليست صغيرة فقط، بل متساوية الأحجام.","الحروف ليست كبيرة فقط، بل متساوية الأحجام."]},
  {"q":"حروف خط النسخ غير مطموسة، أي:","o":["واضحة ومفتوحة","مغلقة","متداخلة","غير مقروءة"],"a":0,"why":"حروف النسخ غير مطموسة، أي واضحة ومفتوحة وغير مغلقة، فيسهل قراءتها وتمييز كل حرف عن الآخر.","ow":["","مغلقة تعاكس كلمة غير مطموسة.","متداخلة ليست معنى غير مطموسة.","غير مطموسة تعني واضحة، وليس غير مقروءة."]},
  {"q":"من الحروف التي لها حالات خاصة في خط النسخ لأنها قد تُطمس:","o":["الباء","الراء","الميم","الدال"],"a":2,"why":"حروف خط النسخ غير مطموسة، عدا حروف قليلة هي الميم والعين والغين، فلها حالات خاصة. أما الباء والراء والدال فواضحة.","ow":["الباء حرف واضح غير مطموس في خط النسخ.","الراء حرف واضح غير مطموس في خط النسخ.","","الدال حرف واضح غير مطموس في خط النسخ."]},
  {"q":"أي الآتي <b>ليس</b> من مميزات خط النسخ؟","o":["سهولة قراءة الكلمات والجمل","إهمال الحركات","تساوي أحجام الحروف","جمال تركيب الحروف"],"a":1,"why":"من مميزات خط النسخ الاهتمام بوضع الحركات، وإهمالها ليس ميزة، لأن الحركات تساعد على القراءة الصحيحة.","ow":["سهولة قراءة الكلمات والجمل ميزة في خط النسخ.","","تساوي أحجام الحروف ميزة في خط النسخ.","جمال تركيب الحروف ميزة في خط النسخ."]},
  {"q":"عند الكتابة بخط النسخ نرسم الحروف بأحجام:","o":["متفاوتة","عشوائية","متساوية","صغيرة جدًا"],"a":2,"why":"من مميزات خط النسخ تساوي أحجام الحروف، فنكتب الحروف بأحجام متساوية ومتناسقة حتى يظهر الخط منظمًا وجميلًا.","ow":["ليست الأحجام متفاوتة، بل متساوية.","ليست الأحجام عشوائية، بل منظمة ومتساوية.","","ليست الأحجام صغيرة جدًا، بل متساوية."]},
  {"q":"الحروف التي استُثنيت من أنها غير مطموسة في خط النسخ هي:","o":["م – ع – غ","ب – ت – ث","د – ذ – ر","ك – ل – ن"],"a":0,"why":"حروف خط النسخ غير مطموسة، ما عدا الميم والعين والغين، فهذه الحروف لها حالات خاصة، وهي التي استُثنيت.","ow":["","ب وت وث حروف غير مطموسة في خط النسخ.","د وذ ور حروف غير مطموسة في خط النسخ.","ك ول ون حروف غير مطموسة في خط النسخ."]},
  {"q":"عند نقل جملة بخط النسخ يجب أن:","o":["نهمل الحركات","نضع الحركات في مواضعها الصحيحة","نغيّر أحجام الحروف","نكتب بسرعة دون تركيز"],"a":1,"why":"من مميزات خط النسخ الاهتمام بوضع الحركات، فعند نقل الجملة نضع الفتحة والضمة والكسرة في مواضعها الصحيحة.","ow":["إهمال الحركات يخالف ميزة خط النسخ.","","تغيير أحجام الحروف يخالف ميزة تساوي الأحجام.","الكتابة بسرعة دون تركيز تضيّع جمال الخط والحركات."]},
  {"q":"خط النسخ تُكتب به:","o":["الإعلانات فقط","الآيات القرآنية في الكتاب","الأرقام فقط","الصور"],"a":1,"why":"خط النسخ هو الخط الذي كُتبت به الآيات القرآنية في كتابنا، وهو خط مناسب لنسخ الكتب والمصاحف.","ow":["الإعلانات تُكتب غالبًا بخطوط زخرفية، وليس خط النسخ فقط.","","الأرقام ليست وحدها ما يُكتب بخط النسخ.","الصور لا تُكتب بخط النسخ."]},
  {"q":"ميزة سهولة القراءة في خط النسخ تعني أن الكلمات والجمل:","o":["صعبة القراءة","لا تُقرأ","سهلة القراءة","تُقرأ بصعوبة"],"a":2,"why":"من مميزات خط النسخ سهولة القراءة، أي أن الكلمات والجمل فيه تُقرأ بسهولة دون تعب.","ow":["صعوبة القراءة ليست ميزة، وخط النسخ سهل.","لا تُقرأ تعني أنه غير واضح، وهذا عكس خط النسخ.","","تُقرأ بصعوبة تعاكس ميزة سهولة القراءة."]},
  {"q":"إذا سُئلت: اذكر ميزتين لخط النسخ، فمن الإجابات الصحيحة:","o":["سهولة القراءة وتساوي الأحجام","إهمال الحركات وطمس الحروف","صعوبة القراءة وجمال الحروف","اختلاف الأحجام وإغلاق الحروف"],"a":0,"why":"من مميزات خط النسخ سهولة القراءة وتساوي أحجام الحروف، فهما ميزتان صحيحتان، أما الإجابات الأخرى فتخالف مميزاته.","ow":["","إهمال الحركات وطمس الحروف ليسا من مميزاته.","صعوبة القراءة ليست ميزة، وإن كان جمال الحروف ميزة.","اختلاف الأحجام وإغلاق الحروف ليسا من مميزاته."]},
  {"q":"الكلمة التي تدل على أن حروف النسخ واضحة ومفتوحة هي:","o":["مطموسة","متداخلة","غير مطموسة","مغلقة"],"a":2,"why":"غير مطموسة تعني أن حروف النسخ واضحة ومفتوحة وغير مغلقة، وهذه الكلمة هي التي ذُكرت في الدرس.","ow":["مطموسة عكس المعنى المطلوب.","متداخلة ليست الكلمة التي تدل على الوضوح.","","مغلقة عكس المعنى المطلوب."]},
  {"q":"العبارة: خط النسخ استُخدم في نسخ المصاحف.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فخط النسخ كان يُستخدم في نسخ الكتب والمصاحف، أي كتابتها، ومن هنا جاء اسمه.","ow":["","العبارة صحيحة، فالمصاحف نُسخت بخط النسخ."]},
  {"q":"العبارة: من مميزات خط النسخ اختلاف أحجام الحروف.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فمن مميزات خط النسخ تساوي أحجام الحروف، وليس اختلافها، فتكون الحروف متناسقة.","ow":["أحجام حروف النسخ متساوية وليست مختلفة.",""]},
  {"q":"العبارة: خط النسخ يهتم بوضع الحركات.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فمن مميزات خط النسخ الاهتمام بوضع الحركات في مواضعها الصحيحة، وهذا يساعد على القراءة الصحيحة.","ow":["","العبارة صحيحة، فالحركات في النسخ توضع في أماكنها."]},
  {"q":"العبارة: كل حروف خط النسخ مطموسة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فحروف خط النسخ غير مطموسة، أي واضحة ومفتوحة، ما عدا الميم والعين والغين فلها حالات خاصة.","ow":["حروف النسخ ليست كلها مطموسة، بل هي واضحة غالبًا.",""]},
  {"q":"العبارة: سهولة القراءة من مميزات خط النسخ.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فسهولة قراءة الكلمات والجمل من مميزات خط النسخ، ولذلك كُتب به القرآن والكتب.","ow":["","العبارة صحيحة، فخط النسخ سهل القراءة."]},
];
window.BANK['a5']['a5-1-14'] = [
  {"q":"عدد خطوات إستراتيجية الخطوات الخمس:","o":["ثلاث","أربع","خمس","ست"],"a":2,"why":"الخطوات خمس هي: أستطلع، أسأل، أقرأ، أستذكر، أراجع. وبهذا العدد سُميت إستراتيجية الخطوات الخمس.","ow":["عدد الخطوات ليس ثلاثًا، بل خمسًا.","عدد الخطوات ليس أربعًا، بل خمسًا.","","عدد الخطوات ليس ستًا، بل خمسًا."]},
  {"q":"الخطوة الثانية في الإستراتيجية هي:","o":["أستطلع","أسأل","أقرأ","أراجع"],"a":1,"why":"الخطوة الثانية هي أسأل، فبعد استطلاع النص أضع عنوانًا للفقرة وأحوله إلى سؤال. أما أستطلع فهي الخطوة الأولى.","ow":["أستطلع هي الخطوة الأولى وليست الثانية.","","أقرأ هي الخطوة الثالثة.","أراجع هي الخطوة الخامسة والأخيرة."]},
  {"q":"الخطوة الثالثة في الإستراتيجية هي:","o":["أستذكر","أراجع","أستطلع","أقرأ"],"a":3,"why":"الخطوة الثالثة هي أقرأ، فبعد أن أضع الأسئلة أقرأ الفقرات بتركيز للبحث عن إجاباتها.","ow":["أستذكر هي الخطوة الرابعة.","أراجع هي الخطوة الخامسة.","أستطلع هي الخطوة الأولى.",""]},
  {"q":"الخطوة التي أنظر فيها نظرة سريعة إلى العنوان والكلمات البارزة هي:","o":["أستطلع","أسأل","أستذكر","أراجع"],"a":0,"why":"خطوة أستطلع هي النظر السريع إلى العنوان والعناوين الجانبية والكلمات البارزة والصور قبل قراءة النص.","ow":["","أسأل هي وضع الأسئلة من العناوين.","أستذكر هي الإجابة عن الأسئلة من الذاكرة.","أراجع هي مقارنة الإجابات بالنص."]},
  {"q":"في خطوة <b>أسأل</b> أعتمد في صياغة السؤال على:","o":["صورة الغلاف","عنوان الفقرة","اسم المؤلف","رقم الصفحة"],"a":1,"why":"في خطوة أسأل أحوّل عنوان الفقرة إلى سؤال باستخدام أداة مناسبة، فنعتمد على العنوان في صياغة السؤال ولا نعتمد على غيره.","ow":["صورة الغلاف لا تُصاغ منها أسئلة الفقرة.","","اسم المؤلف لا يُصاغ منه سؤال عن الفقرة.","رقم الصفحة لا يُصاغ منه سؤال عن الفقرة."]},
  {"q":"في خطوة <b>أقرأ</b> أتحقق من:","o":["عدد الصفحات","دقة صياغة السؤال","اسم الكاتب","حجم الخط"],"a":1,"why":"في خطوة أقرأ أقرأ الفقرة بتركيز، وأتحقق من أن السؤال الذي وضعته دقيق، وأعدّله إن لزم الأمر.","ow":["عدد الصفحات لا علاقة له بخطوة أقرأ.","","اسم الكاتب لا علاقة له بالتحقق من السؤال.","حجم الخط لا علاقة له بالتحقق من السؤال."]},
  {"q":"خطوة <b>أستذكر</b> فيها أجيب عن أسئلتي:","o":["من الذاكرة","من النص مباشرة","من زميلي","من المعجم"],"a":0,"why":"في خطوة أستذكر أجيب عن أسئلتي من الذاكرة دون النظر إلى النص، لأختبر قدرتي على التذكر.","ow":["","الإجابة من النص مباشرة تكون في خطوة أقرأ.","الإجابة من الزميل ليست من خطوات الإستراتيجية.","الإجابة من المعجم ليست من خطوات الإستراتيجية."]},
  {"q":"خطوة <b>أراجع</b> فيها:","o":["أقرأ النص أول مرة","أقارن إجاباتي بالنص للتأكد","أصيغ الأسئلة","أنظر إلى العنوان فقط"],"a":1,"why":"في خطوة أراجع أقارن إجاباتي التي كتبتها من ذاكرتي بما في النص، لأتأكد من صحتها وأصحح الخطأ.","ow":["قراءة النص أول مرة لا تكون في خطوة المراجعة.","","صياغة الأسئلة تكون في خطوة أسأل.","النظر إلى العنوان فقط يكون في خطوة أستطلع."]},
  {"q":"أستخدم السؤال (من؟) للاستفسار عن:","o":["الزمان","المكان","الشخصيات","السبب"],"a":2,"why":"من؟ يُسأل بها عن الشخصيات، مثل: من بطل القصة؟ ومن قال هذا الكلام؟ فهي تحدد من قام بالحدث.","ow":["الزمان نسأل عنه بكلمة متى.","المكان نسأل عنه بكلمة أين.","","السبب نسأل عنه بكلمة لماذا."]},
  {"q":"عندما أسأل (أين؟) فإني أستفسر عن:","o":["الشخصيات","المكان","الزمان","العبرة"],"a":1,"why":"أين؟ يُسأل بها عن المكان، مثل: أين حدثت القصة؟ فهي تحدد موقع الأحداث، ولا يُسأل بها عن الزمان.","ow":["الشخصيات نسأل عنها بكلمة من.","","الزمان نسأل عنه بكلمة متى.","العبرة نسأل عنها بكلمة لماذا."]},
  {"q":"أستخدم السؤال (ماذا؟) للاستفسار عن:","o":["الأحداث","الزمان","المكان","الشخصيات"],"a":0,"why":"ماذا؟ يُسأل بها عن الأحداث، مثل: ماذا حدث في القصة؟ فتساعدنا على معرفة ما جرى فيها.","ow":["","الزمان نسأل عنه بكلمة متى.","المكان نسأل عنه بكلمة أين.","الشخصيات نسأل عنها بكلمة من."]},
  {"q":"أستخدم السؤال (لماذا؟) للاستفسار عن:","o":["المكان","الزمان","السبب أو العبرة","الشخصيات"],"a":2,"why":"لماذا؟ يُسأل بها عن السبب أو العبرة، مثل: لماذا فعل البطل ذلك؟ وما المغزى من القصة؟","ow":["المكان نسأل عنه بكلمة أين.","الزمان نسأل عنه بكلمة متى.","","الشخصيات نسأل عنها بكلمة من."]},
  {"q":"أُحدّد زمن الأحداث بالسؤال:","o":["أين؟","من؟","ماذا؟","متى؟"],"a":3,"why":"متى؟ يُسأل بها عن الزمان لتحديد وقت الأحداث، مثل: متى وقعت القصة؟ ولا نستخدم أين ولا من لسؤال الزمان.","ow":["أين تسأل عن المكان.","من تسأل عن الشخصيات.","ماذا تسأل عن الأحداث.",""]},
  {"q":"إذا لم يكن للفقرة عنوان، ففي خطوة أسأل:","o":["أتركها","أضع لها عنوانًا","أقرؤها فقط","أحذفها"],"a":1,"why":"إذا لم يكن للفقرة عنوان ففي خطوة أسأل أضع لها عنوانًا من عندي، ثم أحوله إلى سؤال.","ow":["لا نترك الفقرة بلا عنوان، بل نضع لها عنوانًا.","","القراءة فقط لا تكفي، فلا بد من وضع عنوان وسؤال.","لا نحذف الفقرة، فكل فقرة لها سؤال."]},
  {"q":"مثال: العنوان (أهمية الأمانة)، فالسؤال المناسب:","o":["ما أهمية الأمانة؟","أين الأمانة؟","متى الأمانة؟","كم الأمانة؟"],"a":0,"why":"نصوغ السؤال من العنوان باستخدام أداة سؤال مناسبة، فعنوان أهمية الأمانة يصبح: ما أهمية الأمانة؟","ow":["","أين تسأل عن المكان، والعنوان يتحدث عن الأهمية.","متى تسأل عن الزمان، والعنوان يتحدث عن الأهمية.","كم تسأل عن العدد، والعنوان يتحدث عن الأهمية."]},
  {"q":"العبارة: الخطوة الأولى في الإستراتيجية هي أستطلع.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالخطوة الأولى أستطلع، حيث ننظر نظرة سريعة إلى النص قبل أن نقرأه كله.","ow":["","العبارة صحيحة، فنبدأ بالاستطلاع ثم نسأل ثم نقرأ."]},
  {"q":"العبارة: خطوة أراجع هي الخطوة الثانية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فأراجع هي الخطوة الخامسة والأخيرة، أما الخطوة الثانية فهي أسأل، حيث نحول العنوان إلى سؤال.","ow":["أراجع ليست الثانية، بل الأخيرة بعد أستذكر.",""]},
  {"q":"العبارة: السؤال (أين؟) يُستخدم للاستفسار عن المكان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فأين يُسأل بها عن المكان، مثل: أين حدثت القصة؟ وهي تحدد موقع الأحداث.","ow":["","العبارة صحيحة، فأين لتحديد المكان."]},
  {"q":"العبارة: في خطوة أستذكر أجيب عن أسئلتي من النص مباشرة.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، ففي خطوة أستذكر أجيب عن أسئلتي من الذاكرة دون النظر إلى النص، أما النظر إلى النص فيكون في المراجعة.","ow":["الإجابة تكون من ذاكرتي في أستذكر وليس من النص مباشرة.",""]},
  {"q":"العبارة: خطوة أستطلع نظرة سريعة على النص.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فخطوة أستطلع نظرة سريعة على النص، كالنظر إلى العنوان والعناوين الجانبية والصور.","ow":["","العبارة صحيحة، فالاستطلاع نظرة سريعة وليس قراءة كاملة."]},
];
window.BANK['a5']['a5-1-15'] = [
  {"q":"معنى <b>لا تلمزوا أنفسكم</b>:","o":["لا يعب بعضكم بعضًا","لا تضربوا بعضكم","لا تعطوا بعضكم","لا تساعدوا بعضكم"],"a":0,"why":"اللمز هو العيب، فمعنى لا تلمزوا أنفسكم: لا يعب بعضكم بعضًا، لأن المسلمين كالنفس الواحدة.","ow":["","لا تضربوا بعضكم ليس معنى لا تلمزوا.","لا تعطوا بعضكم ليس معنى لا تلمزوا.","لا تساعدوا بعضكم ليس معنى لا تلمزوا، بل الإسلام يأمر بالمساعدة."]},
  {"q":"معنى <b>لا تنابزوا بالألقاب</b>:","o":["لا يمدح بعضكم بعضًا","لا يخاطب بعضكم بعضًا بما يكره","لا تحفظوا الألقاب","لا تسافروا معًا"],"a":1,"why":"التنابز بالألقاب هو أن يخاطب الإنسان غيره بما يكره من الأسماء والألقاب، وهو منهي عنه في الآية.","ow":["المدح ليس معنى التنابز بالألقاب، بل هو الثناء.","","لا تحفظوا الألقاب ليس معنى التنابز.","لا تسافروا معًا ليس له علاقة بالتنابز."]},
  {"q":"معنى كلمة <b>الظنّ</b> كما وردت في الآية:","o":["اليقين","الفرح","الشك في الآخرين","الكرم"],"a":2,"why":"الظن في الآية هو الشك في الآخرين وسوء الظن بهم من غير دليل، وهذا هو معناه في النص، وليس اليقين.","ow":["اليقين هو التأكد التام، وهو عكس الظن.","الفرح ليس معنى الظن في الآية.","","الكرم ليس معنى الظن في الآية."]},
  {"q":"المقصود بـ <b>لا تجسّسوا</b>:","o":["لا تساعدوا الناس","لا تتبعوا أسرار الناس ومعايبهم","لا تسألوا","لا تذهبوا"],"a":1,"why":"لا تجسسوا معناها لا تتبعوا أسرار الناس ومعايبهم، فالتجسس هو البحث عن أخطاء الناس.","ow":["لا تساعدوا الناس ليس معنى لا تجسسوا.","","لا تسألوا ليس معنى لا تجسسوا.","لا تذهبوا ليس معنى لا تجسسوا."]},
  {"q":"معنى <b>لا يغتب</b>:","o":["لا يذكر عيوب غيره في غيبته","لا يغيب عن المدرسة","لا يغضب","لا يسافر"],"a":0,"why":"الغيبة أن تذكر عيوب غيرك في غيابه، فمعنى لا يغتب أحدكم: لا يذكر عيوب غيره وهو غائب.","ow":["","الغياب عن المدرسة ليس معنى الغيبة.","الغضب ليس معنى الغيبة.","السفر ليس معنى الغيبة."]},
  {"q":"المقصود بكلمة <b>القرين</b>:","o":["العدو","المعلم","الجار","الصديق"],"a":3,"why":"القرين هو الصديق الملازم لك الذي يصاحبك، وهذا هو معناها في النص، وليس العدو ولا المعلم ولا الجار.","ow":["العدو عكس الصديق.","المعلم ليس معنى القرين.","الجار هو من يسكن بجانبك وليس القرين.",""]},
  {"q":"معنى <b>يشين</b>:","o":["يزين","يعيب وينقص","يمدح","يعين"],"a":1,"why":"يشين معناها يعيب وينقص من قدر الإنسان، فالعمل السيئ يشين صاحبه أي يعيبه، وهي عكس يزين.","ow":["يزين ضد يشين، فمعناها يجمّل.","","يمدح ضد يشين في المعنى.","يعين معناها يساعد وليس يعيب."]},
  {"q":"المقصود بكلمة <b>ثرثارة</b>:","o":["كثير الكلام","قليل الكلام","مريض","كريم"],"a":0,"why":"الثرثارة هي كثيرة الكلام بلا فائدة، وهذا هو معناها في النص، وهي عكس قليلة الكلام.","ow":["","قليل الكلام ضد الثرثار.","المريض ليس معنى ثرثارة.","الكريم ليس معنى ثرثارة."]},
  {"q":"معنى <b>اللئيم</b>:","o":["الكريم","المريض","ذو الأخلاق السيئة","الصديق"],"a":2,"why":"اللئيم هو صاحب الأخلاق السيئة، ويقابله الكريم صاحب الأخلاق الحسنة، فالكريم ضده وليس معناه.","ow":["الكريم ضد اللئيم وليس معناه.","المريض ليس معنى اللئيم.","","الصديق ليس معنى اللئيم."]},
  {"q":"المقصود بكلمة <b>الأجرب</b>:","o":["الغني","المريض بمرض في جلده","الصادق","الطويل"],"a":1,"why":"الأجرب هو المريض بمرض في جلده، وهذا هو معنى الكلمة كما وردت في النص، وليس الغني ولا الصادق.","ow":["الغني ليس معنى الأجرب.","","الصادق ليس معنى الأجرب.","الطويل ليس معنى الأجرب."]},
  {"q":"معنى <b>يحجب</b>:","o":["يمنع","يعطي","يقرأ","يكتب"],"a":0,"why":"يحجب معناها يمنع، فنقول: حجب الشيء أي منعه من الوصول إلينا، وعكسها كلمة يعطي التي تعني يقدّم.","ow":["","يعطي ضد يمنع، وليس معنى يحجب.","يقرأ ليس معنى يحجب.","يكتب ليس معنى يحجب."]},
  {"q":"المقصود بعبارة <b>أجل مسمّى</b>:","o":["وقت مفتوح","وقت محدّد","مكان بعيد","اسم شخص"],"a":1,"why":"أجل مسمى أي وقت محدد ومعلوم، فالمسمى هو المحدد، وليس وقتًا مفتوحًا أو غير معروف.","ow":["وقت مفتوح ليس معنى أجل مسمى، لأن المسمى هو المحدد.","","المكان البعيد ليس معنى أجل مسمى.","اسم الشخص ليس معنى أجل مسمى."]},
  {"q":"ضد كلمة <b>الخيانة</b>:","o":["الأمانة","الشك","الكذب","الظلم"],"a":0,"why":"الخيانة ضدها الأمانة، فالأمين يحفظ ما اؤتمن عليه، والخائن لا يحفظه. والأضداد كلمات معناها متعاكس.","ow":["","الشك ليس ضد الخيانة، بل ضده اليقين.","الكذب ضده الصدق، وليس ضد الخيانة.","الظلم ضده العدل، وليس ضد الخيانة."]},
  {"q":"ضد كلمة <b>الشك</b>:","o":["الظن","اليقين","الخيانة","الشر"],"a":1,"why":"اليقين ضد الشك، فاليقين هو التأكد التام، والشك هو التردد وعدم التأكد. والأضداد كلمات معناها متعاكس.","ow":["الظن قريب في المعنى من الشك، وليس ضده.","","الخيانة ليست ضد الشك.","الشر ليس ضد الشك."]},
  {"q":"ضد كلمة <b>شرّ</b>:","o":["ضرر","سوء","خير","لؤم"],"a":2,"why":"الخير ضد الشر، فالخير كل ما ينفع الناس، والشر كل ما يضرهم. والأضداد كلمات معناها متعاكس.","ow":["ضرر يقارب الشر في المعنى وليس ضده.","سوء يقارب الشر في المعنى وليس ضده.","","لؤم قريب من الشر وليس ضده."]},
  {"q":"الكلمتان <b>يشين</b> و<b>يعيب</b> بينهما علاقة:","o":["تضاد","تقارب في المعنى (ترادف)","لا علاقة","جمع"],"a":1,"why":"يشين ويعيب معناهما متقارب، فهما مترادفتان. والمترادفات كلمات مختلفة في اللفظ متقاربة في المعنى.","ow":["التضاد يكون بين الكلمات المتعاكسة، وهنا المعنى متقارب.","","بين الكلمتين علاقة وهي التقارب في المعنى.","يشين ويعيب فعلان وليستا جمعًا."]},
  {"q":"العبارة: القرين هو الصديق.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالقرين هو الصديق الملازم الذي يصاحبك، وهذا هو معنى الكلمة في النص.","ow":["","العبارة صحيحة، فالقرين هو الصديق."]},
  {"q":"العبارة: اللئيم هو الكريم.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فاللئيم هو صاحب الأخلاق السيئة، أما الكريم فضده، فلا يمكن أن يكون اللئيم هو الكريم.","ow":["اللئيم ليس الكريم، بل ضده.",""]},
  {"q":"العبارة: الأضداد كلمات معناها متعاكس.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالأضداد كلمات معناها متعاكس، مثل: الأمانة والخيانة، والخير والشر، واليقين والشك.","ow":["","العبارة صحيحة، فمعنى الأضداد التعاكس."]},
  {"q":"العبارة: المترادفات معناها متعاكس.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالمترادفات كلمات معناها متقارب مثل يشين ويعيب، أما المتعاكسة فهي الأضداد.","ow":["المترادفات معناها متقارب وليس متعاكسًا.",""]},
];
window.BANK['a5']['a5-1-16'] = [
  {"q":"من عناصر القصة:","o":["الإعلان","العقدة","الوسيلة","الجمهور"],"a":1,"why":"عناصر القصة: الشخصيات، والمكان والزمان، والأحداث، والعقدة، والحل. فالعقدة من عناصر القصة.","ow":["الإعلان ليس من عناصر القصة، بل هو نص آخر.","","الوسيلة ليست من عناصر القصة.","الجمهور ليس من عناصر القصة."]},
  {"q":"الشخصيات في القصة هم:","o":["من يشارك في القصة","مكان الأحداث","زمان الأحداث","حل المشكلة"],"a":0,"why":"الشخصيات هم الأشخاص أو الكائنات الذين يشاركون في أحداث القصة، ونسأل عنهم بقولنا: من؟","ow":["","مكان الأحداث نسأل عنه بقولنا: أين؟","زمان الأحداث نسأل عنه بقولنا: متى؟","حل المشكلة عنصر آخر من عناصر القصة."]},
  {"q":"يُسأل بـ (أين؟) عن:","o":["الزمان","العبرة","مكان الأحداث","الشخصيات"],"a":2,"why":"أين؟ يُسأل بها عن مكان الأحداث، أي الموقع الذي حدثت فيه القصة، مثل: أين حدثت القصة؟","ow":["الزمان نسأل عنه بكلمة متى.","العبرة نسأل عنها بكلمة لماذا.","","الشخصيات نسأل عنها بكلمة من."]},
  {"q":"يُسأل بـ (من؟) عن:","o":["الشخصيات","الزمان","الحل","العبرة"],"a":0,"why":"الشخصيات هم من يشاركون في القصة، ونسأل عنهم بكلمة من، مثل: من بطل القصة؟ وهذا يختلف عن الزمان والمكان والحل.","ow":["","الزمان نسأل عنه بكلمة متى.","الحل ليس شخصية، وهو عنصر آخر.","العبرة نسأل عنها بكلمة لماذا."]},
  {"q":"الذي يفكّ المشكلة في القصة هو:","o":["العقدة","الحل","العنوان","المكان"],"a":1,"why":"الحل هو الذي يفك المشكلة التي واجهت الشخصيات، ويأتي بعد العقدة وينهيها، فلا تكون العقدة هي ما يفك المشكلة.","ow":["العقدة هي المشكلة نفسها، وليست ما يفكها.","","العنوان ليس من عناصر القصة.","المكان ليس هو ما يفك المشكلة."]},
  {"q":"العقدة هي:","o":["الحل","الشخصيات","المشكلة التي تواجه الشخصيات","العنوان"],"a":2,"why":"العقدة هي المشكلة التي تواجه الشخصيات في القصة، ثم يأتي الحل لينهيها، فالعقدة ليست هي الحل.","ow":["الحل هو ما يفك العقدة وليس العقدة نفسها.","الشخصيات هم من يشاركون في القصة وليسوا العقدة.","","العنوان ليس هو العقدة."]},
  {"q":"مكان الأحداث في قصة خشبة المقترض الأمين:","o":["بلد على ساحل البحر","صحراء","جبل","مدرسة"],"a":0,"why":"تدور القصة في بلد على ساحل البحر، وهذا هو مكان الأحداث الذي نعرفه بالسؤال: أين حدثت القصة؟","ow":["","الصحراء ليست مكان الأحداث.","الجبل ليس مكان الأحداث.","المدرسة ليست مكان الأحداث."]},
  {"q":"زمن الأحداث في قصة خشبة المقترض الأمين:","o":["زمننا هذا","زمن بني إسرائيل","زمن الصحابة","زمن الخلفاء"],"a":1,"why":"زمن أحداث القصة هو زمن بني إسرائيل، وهذا ما نعرفه بالسؤال: متى حدثت القصة؟ فهي قصة قديمة.","ow":["زمننا هذا ليس زمن القصة، فالقصة قديمة.","","زمن الصحابة ليس زمن هذه القصة.","زمن الخلفاء ليس زمن هذه القصة."]},
  {"q":"في قصة المقترض الأمين، المشكلة التي واجهته:","o":["ضاع ماله","لم يجد مركبًا عند موعد السداد","مرض","فقد صديقه"],"a":1,"why":"عقدة القصة أنه لما جاء موعد السداد لم يجد مركبًا يحمله ليوفي دينه، فهذه هي المشكلة التي واجهته.","ow":["ضياع المال ليس المشكلة المذكورة في القصة.","","المرض ليس المشكلة المذكورة في القصة.","فقد الصديق ليس المشكلة المذكورة في القصة."]},
  {"q":"حل المشكلة في قصة المقترض الأمين:","o":["اقترض مالًا جديدًا","ألقى الدين في البحر","حشا خشبة بألف دينار ووضع معها رسالة","سافر بنفسه"],"a":2,"why":"حل المشكلة أنه حشا خشبة بألف دينار ووضع معها رسالة، ثم رماها في البحر، فتحقق وفاء الدين.","ow":["اقتراض مال جديد ليس الحل المذكور.","إلقاء الدين في البحر ليس المقصود، فقد وضع المال في خشبة مع رسالة.","","السفر بنفسه ليس الحل، فقد لم يجد مركبًا."]},
  {"q":"يُسأل بـ (متى؟) عن:","o":["الأحداث","زمان الأحداث","المكان","الشخصيات"],"a":1,"why":"متى؟ يُسأل بها عن زمان الأحداث، أي وقت وقوع القصة، أما الأحداث نفسها فنسأل عنها بكلمة ماذا.","ow":["الأحداث نسأل عنها بكلمة ماذا.","","المكان نسأل عنه بكلمة أين.","الشخصيات نسأل عنها بكلمة من."]},
  {"q":"عناصر القصة عددها:","o":["ثلاثة","أربعة","خمسة","ستة"],"a":2,"why":"عناصر القصة خمسة: الشخصيات، والمكان والزمان، والأحداث، والعقدة، والحل، فعددها خمسة وليس غير ذلك.","ow":["عناصر القصة أكثر من ثلاثة.","عناصر القصة خمسة وليست أربعة.","","عناصر القصة خمسة وليست ستة."]},
  {"q":"خريطة القصة تتكوّن من:","o":["المكان والزمان والشخصيات والمشكلة والأحداث والحل","الجمهور والوسيلة","المعلن والمعلن عنه","الأمر والنهي"],"a":0,"why":"خريطة القصة تتكون من المكان والزمان والشخصيات والمشكلة والأحداث والحل، وهي عناصر القصة التي نستخرجها.","ow":["","الجمهور والوسيلة من عناصر الإعلان.","المعلن والمعلن عنه من عناصر الإعلان.","الأمر والنهي من أساليب اللغة وليست عناصر القصة."]},
  {"q":"الأحداث في القصة هي:","o":["الحوادث المتتابعة","مكان القصة","عنوان القصة","أسماء الأبطال"],"a":0,"why":"الأحداث هي الحوادث التي تقع في القصة واحدة بعد الأخرى، وتتسلسل حتى تصل إلى العقدة ثم الحل.","ow":["","مكان القصة هو الموقع الذي تدور فيه، وليس الأحداث.","عنوان القصة ليس هو الأحداث.","أسماء الأبطال هي الشخصيات."]},
  {"q":"أبدأ بإعادة كتابة القصة بذكر:","o":["الحل","المكان والزمان والشخصيات","العبرة فقط","العقدة قبل الأحداث"],"a":1,"why":"عند إعادة كتابة القصة نبدأ بذكر المكان والزمان والشخصيات، ثم الأحداث، ثم المشكلة والحل، ثم العبرة.","ow":["لا نبدأ بالحل، فالحل يأتي في النهاية.","","العبرة تأتي في آخر القصة وليست أول ما نكتب.","العقدة تأتي بعد الأحداث، وليست قبلها."]},
  {"q":"العبارة: العقدة هي المشكلة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالعقدة هي المشكلة التي تواجه الشخصيات في القصة، والحل يأتي بعدها.","ow":["","العبارة صحيحة، فالعقدة والمشكلة معنى واحد."]},
  {"q":"العبارة: يُسأل بـ (أين؟) عن الشخصيات.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فأين يُسأل بها عن المكان، أما الشخصيات فنسأل عنها بكلمة من، فلا نخلط بين السؤالين.","ow":["أين للمكان وليس للشخصيات، فالعبارة غير صحيحة.",""]},
  {"q":"العبارة: الحل يأتي بعد العقدة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالحل هو الطريقة التي تُحلّ بها المشكلة، ويأتي بعد العقدة وينهيها، وليس قبلها.","ow":["","العبارة صحيحة، فالحل بعد العقدة وليس قبلها."]},
  {"q":"العبارة: (لماذا؟) تساعدنا في معرفة العبرة.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فلماذا يُسأل بها عن السبب، وتساعدنا على استخلاص العبرة أو المغزى من القصة.","ow":["","العبارة صحيحة، فلماذا لمعرفة العبرة."]},
  {"q":"العبارة: الزمان في القصة هو مكان الأحداث.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالزمان هو وقت وقوع الأحداث، أما مكان الأحداث فهو الموقع الذي حدثت فيه القصة.","ow":["الزمان ليس هو المكان، فكل واحد منهما عنصر مستقل.",""]},
];
window.BANK['a5']['a5-1-17'] = [
  {"q":"المُعلِن هو:","o":["موضوع الإعلان","من ينشر الإعلان","وسيلة الإعلان","الجمهور"],"a":1,"why":"المعلِن هو من ينشر الإعلان، سواء كان شخصًا أو شركة تجارية أو جهة حكومية مثل وزارة الصحة.","ow":["موضوع الإعلان هو المعلَن عنه وليس المعلِن.","","وسيلة الإعلان هي ما ينشر الإعلان عن طريقه.","الجمهور هم من يتوجه إليهم الإعلان."]},
  {"q":"المُعلَن عنه هو:","o":["موضوع الإعلان","ناشر الإعلان","مكان الإعلان","الجمهور"],"a":0,"why":"المعلَن عنه هو الشيء الذي يتم الإعلان عنه، أي موضوع الإعلان، مثل سلعة أو ندوة أو مسابقة.","ow":["","ناشر الإعلان هو المعلِن وليس المعلَن عنه.","مكان الإعلان هو الحدود الجغرافية للحملة.","الجمهور هم الناس الذين يتوجه إليهم الإعلان."]},
  {"q":"جمهور الإعلان هو:","o":["من ينشر الإعلان","مكان النشر","من يتوجه إليهم الإعلان","مدة الحملة"],"a":2,"why":"جمهور الإعلان هم الناس الذين يتوجه إليهم الإعلان ويقصدهم، مثل الطلاب أو الأطفال أو النساء.","ow":["من ينشر الإعلان هو المعلِن.","مكان النشر هو الوسيلة.","","مدة الحملة هي زمن الإعلان."]},
  {"q":"وسيلة الإعلان هي:","o":["موضوعه","من ينشره","مكان نشره وعرضه","زمنه"],"a":2,"why":"وسيلة الإعلان هي الطريقة أو المكان الذي ينشر فيه الإعلان ويُعرض، مثل الصحف والمجلات والتلفاز والملصقات.","ow":["موضوع الإعلان هو المعلَن عنه وليس الوسيلة.","من ينشر الإعلان هو المعلِن.","","زمن الإعلان هو المدة الإعلانية."]},
  {"q":"مكان الإعلان هو:","o":["الحدود الجغرافية للحملة الإعلانية","المدة","الصحف","المعلن"],"a":0,"why":"مكان الإعلان هو الحدود الجغرافية للحملة الإعلانية، أي المنطقة التي يصل إليها الإعلان.","ow":["","المدة الإعلانية هي زمن الإعلان وليس مكانه.","الصحف هي وسيلة الإعلان وليست مكانه الجغرافي.","المعلِن هو من ينشر الإعلان وليس مكانه."]},
  {"q":"زمن الإعلان هو:","o":["الحدود الجغرافية","المدة الإعلانية للحملة","الجمهور","الموضوع"],"a":1,"why":"زمن الإعلان هو المدة الإعلانية للحملة، أي المدة التي يستمر فيها نشر الإعلان وعرضه.","ow":["الحدود الجغرافية هي مكان الإعلان وليس زمنه.","","الجمهور هم من يتوجه إليهم الإعلان.","الموضوع هو المعلَن عنه وليس زمنه."]},
  {"q":"من أمثلة المعلِن:","o":["ندوة","مسابقة","وزارة الصحة","ملصق"],"a":2,"why":"وزارة الصحة جهة حكومية تنشر الإعلان، فهي معلِن. أما الندوة والمسابقة فهما موضوع الإعلان، والملصق وسيلة.","ow":["الندوة هي ما يُعلَن عنه وليست من ينشر الإعلان.","المسابقة هي ما يُعلَن عنه وليست من ينشر الإعلان.","","الملصق وسيلة من وسائل الإعلان وليس ناشره."]},
  {"q":"من أمثلة المعلَن عنه:","o":["مسابقة","شركة","صحيفة","تلفاز"],"a":0,"why":"المسابقة مما يُعلَن عنه، أي موضوع الإعلان، فهي المعلَن عنه. أما الشركة فمعلِن، والصحيفة والتلفاز وسيلتان.","ow":["","الشركة ناشرة الإعلان وهي المعلِن.","الصحيفة وسيلة من وسائل الإعلان.","التلفاز وسيلة من وسائل الإعلان."]},
  {"q":"من أمثلة وسيلة الإعلان:","o":["الأطفال","ملصقات","وزارة","محاضرة"],"a":1,"why":"الملصقات من وسائل الإعلان مثل الصحف والمجلات والتلفاز، فهي طريقة أو مكان لعرض الإعلان ونشره.","ow":["الأطفال جمهور وليسوا وسيلة.","","الوزارة جهة معلِنة وليست وسيلة.","المحاضرة مما يُعلَن عنه وليست وسيلة."]},
  {"q":"من أمثلة جمهور الإعلان:","o":["الطلاب","الصحف","المجلات","الملصقات"],"a":0,"why":"الطلاب من جمهور الإعلان، وهم الناس الذين يتوجه إليهم الإعلان، مثل الأطفال والنساء والرجال.","ow":["","الصحف وسيلة من وسائل الإعلان.","المجلات وسيلة من وسائل الإعلان.","الملصقات وسيلة من وسائل الإعلان."]},
  {"q":"في إعلان مدرسة عن مسابقة قراءة للأطفال، الجمهور هو:","o":["المدرسة","المسابقة","الأطفال","الإذاعة"],"a":2,"why":"الإعلان موجّه إلى الأطفال، فهم جمهور الإعلان. أما المدرسة فهي المعلِن، والمسابقة هي المعلَن عنه.","ow":["المدرسة هي المعلِن الذي ينشر الإعلان.","المسابقة هي المعلَن عنه، أي موضوع الإعلان.","","الإذاعة وسيلة الإعلان وليست جمهوره."]},
  {"q":"في إعلان مدرسة عن مسابقة قراءة، المعلَن عنه هو:","o":["الأطفال","المدرسة","الإذاعة","مسابقة القراءة"],"a":3,"why":"المعلَن عنه هو موضوع الإعلان، وهنا هو مسابقة القراءة، أما المدرسة فهي المعلِن الذي ينشر الإعلان.","ow":["الأطفال هم جمهور الإعلان وليسوا موضوعه.","المدرسة هي المعلِن وليست موضوع الإعلان.","الإذاعة وسيلة الإعلان وليست موضوعه.",""]},
  {"q":"السؤال (لمن الإعلان؟) نسأل به عن:","o":["الجمهور","المعلن","الزمن","المكان"],"a":0,"why":"السؤال لمن الإعلان؟ نسأل به عن الجمهور، أي من يتوجه إليهم الإعلان، مثل الأطفال أو الطلاب.","ow":["","المعلِن نسأل عنه بكلمة من ينشر الإعلان.","الزمن نسأل عنه بالمدة الإعلانية.","المكان نسأل عنه بحدود الحملة الجغرافية."]},
  {"q":"السؤال (مَن المعلِن؟) نسأل به عن:","o":["الموضوع","الناشر","الوسيلة","الزمن"],"a":1,"why":"السؤال من المعلِن؟ نسأل به عن ناشر الإعلان، أي الشخص أو الشركة أو الجهة التي نشرته.","ow":["الموضوع نسأل عنه بكلمة ما المعلَن عنه.","","الوسيلة نسأل عنها بكلمة بأي وسيلة.","الزمن نسأل عنه بكلمة متى."]},
  {"q":"عناصر الإعلان تشمل:","o":["العقدة والحل","المعلِن والمعلَن عنه والجمهور والوسيلة والمكان والزمن","الفاعل والمفعول","المبتدأ والخبر"],"a":1,"why":"عناصر الإعلان: المعلِن، والمعلَن عنه، وجمهور الإعلان، ووسيلة الإعلان، ومكان الإعلان، وزمن الإعلان.","ow":["العقدة والحل من عناصر القصة وليست عناصر الإعلان.","","الفاعل والمفعول من أركان الجملة وليست عناصر الإعلان.","المبتدأ والخبر ركنا الجملة الاسمية وليسا عناصر الإعلان."]},
  {"q":"العبارة: المعلِن هو من ينشر الإعلان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فالمعلِن هو من ينشر الإعلان، وقد يكون شخصًا أو شركة تجارية أو جهة حكومية.","ow":["","العبارة صحيحة، فالمعلِن هو الناشر."]},
  {"q":"العبارة: الصحف والتلفاز تمثل جمهور الإعلان.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فالصحف والتلفاز هي وسائل الإعلان أي طرق نشره، أما جمهور الإعلان فهم الناس الذين يتوجه إليهم.","ow":["الصحف والتلفاز ليست جمهورًا بل وسائل نشر.",""]},
  {"q":"العبارة: المدة الإعلانية للحملة تسمى زمن الإعلان.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فزمن الإعلان هو المدة الإعلانية للحملة، أي المدة التي يستمر فيها الإعلان.","ow":["","العبارة صحيحة، فالمدة الإعلانية هي الزمن."]},
  {"q":"العبارة: مكان الإعلان هو المدة الإعلانية.","o":["صح","خطأ"],"a":1,"why":"العبارة خطأ، فمكان الإعلان هو الحدود الجغرافية للحملة، أما المدة الإعلانية فهي زمن الإعلان.","ow":["المدة الإعلانية هي زمن الإعلان وليست مكانه.",""]},
  {"q":"العبارة: وزارة الصحة يمكن أن تكون معلِنًا.","o":["صح","خطأ"],"a":0,"why":"العبارة صحيحة، فوزارة الصحة جهة حكومية تنشر الإعلانات، ولذلك يمكن أن تكون معلِنًا.","ow":["","العبارة صحيحة، فالجهة الحكومية تكون معلِنة."]},
];

